INSERT INTO collected_data.media_assets (id, bucket, object_key, mime_type, byte_size, width, height, source_url, metadata) VALUES ('71583f4c9b3c65a2aebc460b32f04414eefdc715616a62618af08b6db6c7ef69', 'safescan-media', 'datasets/collection-20261009/images/71583f4c9b3c65a2aebc460b32f04414eefdc715616a62618af08b6db6c7ef69.jpg', 'image/jpeg', 55960, 640, 480, 'https://i.sstatic.net/xblgj.jpg', '{"id": "71583f4c9b3c65a2aebc460b32f04414eefdc715616a62618af08b6db6c7ef69", "path": "images/71583f4c9b3c65a2aebc460b32f04414eefdc715616a62618af08b6db6c7ef69.jpg", "width": 640, "height": 480, "url": "https://i.sstatic.net/xblgj.jpg", "role": "reported_fault_context_candidate", "review": null, "rights_status": "unknown", "record_ids": ["diy-183907"], "source_files": ["repair-integrated-20261009\\images\\indoor-183907-0.jpg", "indoor-repair-20261009\\media\\000\\06.jpg"], "source_metadata": [{"file": "indoor-repair-20261009\\clean.json", "record": {"id": "183907-0", "question_id": 183907, "category": "drain_blockage", "kind": "image", "url": "https://i.sstatic.net/xblgj.jpg", "alt": "sink picture ", "source_url": "https://diy.stackexchange.com/questions/183907/double-sink-clogged-in-mobile-home", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 640, "height": 480, "final_url": "https://i.sstatic.net/xblgj.jpg", "local_path": "media/000/06.jpg", "sha256": "71583f4c9b3c65a2aebc460b32f04414eefdc715616a62618af08b6db6c7ef69", "retrieved_at": "2026-10-09T08:52:12.809504+00:00", "visual_review": "contact_sheet_review_2026-10-09", "review_note": "水槽或排水管照片；排水不畅依据原帖，照片不能确认堵塞原因。", "evidence_level": "reported_symptom_context"}}, {"file": "indoor-repair-20261009\\dataset.json", "record": {"id": "183907-0", "question_id": 183907, "category": "drain_blockage", "kind": "image", "url": "https://i.sstatic.net/xblgj.jpg", "alt": "sink picture ", "source_url": "https://diy.stackexchange.com/questions/183907/double-sink-clogged-in-mobile-home", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 640, "height": 480, "final_url": "https://i.sstatic.net/xblgj.jpg", "local_path": "media/000/06.jpg", "sha256": "71583f4c9b3c65a2aebc460b32f04414eefdc715616a62618af08b6db6c7ef69", "retrieved_at": "2026-10-09T08:52:12.809504+00:00"}}, {"file": "repair-integrated-20261009\\dataset.json", "record": {"id": "indoor-183907-0", "group": "indoor", "category": "drain_blockage", "category_zh": "排水不畅", "title": "Double sink clogged in mobile home", "reported_symptom": "Was working through a clogged sink yesterday, had a partial flow, went to my parents for a bit, came back to find husband and roommate had decided to take it into their own hands, got some bleach smelling chemical and a plunger and there was no longer a partial flow. I should also mention we have a septic tank. Watched this video: https://youtu.be/JeurinbyqhQ Removed pea trap and confirmed clog isn’t there. The rest of my pipes differ from the video so I’m not sure how much I should remove. I was able to get a drain snake in the horizontal part but was unable to go down. There is a little thing near the bottom, black plug with a square twist thing. Not sure if it okay to remove that. Update, took the access plug thing out. Clog seems to be below that. Post two snakes. First snake made the water go down to where I could just see it. After second snake I can’t see the water. Our plumber previously gave us some Bio-Clean drain cleaner. Going to close everything up and treat the pipes with that, see where we stand after a few hours of that sitting.", "display_label": "排水不畅", "label_basis": "reported_symptom_context", "demo_status": "待维修（演示设定）", "demo_status_is_synthetic": true, "actual_work_order": false, "diagnosis_confirmed": false, "source_url": "https://diy.stackexchange.com/questions/183907/double-sink-clogged-in-mobile-home", "image_url": "https://i.sstatic.net/xblgj.jpg", "author": "Chelsea", "content_license": "CC 