INSERT INTO collected_data.media_assets (id, bucket, object_key, mime_type, byte_size, width, height, source_url, metadata) VALUES ('5edbd8fa7c2751bdd13105c463a0ba281fa59e6e80c28312de9fe2c8c1a72980', 'safescan-media', 'datasets/collection-20261009/images/5edbd8fa7c2751bdd13105c463a0ba281fa59e6e80c28312de9fe2c8c1a72980.jpg', 'image/jpeg', 113952, 600, 318, 'https://i.sstatic.net/YmAiJ.jpg', '{"id": "5edbd8fa7c2751bdd13105c463a0ba281fa59e6e80c28312de9fe2c8c1a72980", "path": "images/5edbd8fa7c2751bdd13105c463a0ba281fa59e6e80c28312de9fe2c8c1a72980.jpg", "width": 600, "height": 318, "url": "https://i.sstatic.net/YmAiJ.jpg", "role": "reported_fault_context_candidate", "review": null, "rights_status": "unknown", "record_ids": ["diy-184717"], "source_files": ["repair-integrated-20261009\\images\\indoor-184717-0.jpg", "indoor-repair-20261009\\media\\020\\01.jpg"], "source_metadata": [{"file": "indoor-repair-20261009\\clean.json", "record": {"id": "184717-0", "question_id": 184717, "category": "socket_damage", "kind": "image", "url": "https://i.sstatic.net/YmAiJ.jpg", "alt": "Burn-out outlet and plug", "source_url": "https://diy.stackexchange.com/questions/184717/can-a-cooking-oil-spill-over-cause-a-burnt-out-outlet", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 600, "height": 318, "final_url": "https://i.sstatic.net/YmAiJ.jpg", "local_path": "media/020/01.jpg", "sha256": "5edbd8fa7c2751bdd13105c463a0ba281fa59e6e80c28312de9fe2c8c1a72980", "retrieved_at": "2026-10-09T08:52:44.780994+00:00", "visual_review": "contact_sheet_review_2026-10-09", "review_note": "前五张可见明显焦黑或熔损；77410-0仅作线缆部位背景，不确认烧损。", "evidence_level": "visible_discoloration_or_material_damage_cause_unconfirmed"}}, {"file": "indoor-repair-20261009\\dataset.json", "record": {"id": "184717-0", "question_id": 184717, "category": "socket_damage", "kind": "image", "url": "https://i.sstatic.net/YmAiJ.jpg", "alt": "Burn-out outlet and plug", "source_url": "https://diy.stackexchange.com/questions/184717/can-a-cooking-oil-spill-over-cause-a-burnt-out-outlet", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 600, "height": 318, "final_url": "https://i.sstatic.net/YmAiJ.jpg", "local_path": "media/020/01.jpg", "sha256": "5edbd8fa7c2751bdd13105c463a0ba281fa59e6e80c28312de9fe2c8c1a72980", "retrieved_at": "2026-10-09T08:52:44.780994+00:00"}}, {"file": "repair-integrated-20261009\\dataset.json", "record": {"id": "indoor-184717-0", "group": "indoor", "category": "socket_damage", "category_zh": "插座损伤", "title": "Can a cooking oil spill-over cause a burnt-out outlet?", "reported_symptom": "A cooking stove with electricity and natural gas has been in place for 20 years. Last month I did deep frying, some of the oil went overboard, touched the electric plate, and some of it instantly vaporized into smoke. The oil also left a definite stain on the electric plate. Note that I didn''t smell anything burned, and that the electric plate and cooktop was 1 meter from the power plug. I didn''t use the cooktop for a month and yesterday, when I turned on an oven daisy-chained to the same outlet, the house circuit breaker went off and I smelled something burned, which I then identified as burnt plastic. The outlet was burnt-out along with the electric plug of the cooktop: (I found it hard to take a good picture because the burnt area is the blackest of the black.) I did not find any residue of oil near the outlet. The cooktop has been in place for many years in an area by the seaside with much salt, humidity (up to 80%), so metal often corrodes and rusts. Could cooking oil cause the outlet to arc and burn out? If not, what is the most likely cause? Update Here is a photo of the house''s electric panel. The tripped switch was third from the top left:", "display_label": "插座损伤", "label_basis": "visible_discoloration_or_material_damage_cause_unconfirmed", "demo_status": "待维修（演示设定）", "demo_status_is_synthetic": true, "actual_work_order": false, "diagnosis_confirmed": false, "source_url": "https://diy.stackexchange.com/questions/184717/can-a-cooking-oil-spill-over-cause-a-burnt-out-outlet", "image_url": "https://i.sstatic.net/YmAiJ.jpg", "author": "ginjaemocoes", "content_license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "image_rights_status": "not_independently_verified", "source_record_file": "D:\\project\\Safescan_agent\\data\\collection-pilot\\indoor-repair-20261009\\clean.json", "source_image_path": "D:\\project\\Safescan_agent\\data\\collection-pilot\\indoor-repair-20261009\\media\\020\\01.jpg", "review_note": "前五张可见明显焦黑或熔损；77410-0仅作线缆部位背景，不确认烧损。", "local_path": "images/indoor-184717-0.jpg", "sha256": "5edbd8fa7c2751bdd13105c463a0ba281fa59e6e80c28312de9fe2c8c1a72980", "country": null}}, {"file": "indoor-repair-20261009\\media\\020\\outcomes.json", "record": {"id": "184717-0", "question_id": 184717, "category": "socket_damage", "kind": "image", "url": "https://i.sstatic.net/YmAiJ.jpg", "alt": "Burn-out outlet and plug", "source_url": "https://diy.stackexchange.com/questions/184717/can-a-cooking-oil-spill-over-cause-a-burnt-out-outlet", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 600, "height": 318, "final_url": "https://i.sstatic.net/YmAiJ.jpg", "local_path": "01.jpg", "sha256": "5edbd8fa7c2751bdd13105c463a0ba281fa59e6e80c28312de9fe2c8c1a72980", "retrieved_at": "2026-10-09T08:52:44.780994+00:00"}}]}') ON CONFLICT (id) DO UPDATE SET bucket=EXCLUDED.bucket, object_key=EXCLUDED.object_key, mime_type=EXCLUDED.mime_type, byte_size=EXCLUDED.byte_size, width=EXCLUDED.width, height=EXCLUDED.height, source_url=EXCLUDED.source_url, metadata=EXCLUDED.metadata;
