INSERT INTO collected_data.media_assets (id, bucket, object_key, mime_type, byte_size, width, height, source_url, metadata) VALUES ('b38028c2e750ace15be23c7b3915d9c13a4ac99265c3627f6a0c8c8188267d32', 'safescan-media', 'datasets/collection-20261009/images/b38028c2e750ace15be23c7b3915d9c13a4ac99265c3627f6a0c8c8188267d32.jpg', 'image/jpeg', 203574, 1536, 2048, 'https://i.sstatic.net/2vCzw9M6.jpg', '{"id": "b38028c2e750ace15be23c7b3915d9c13a4ac99265c3627f6a0c8c8188267d32", "path": "images/b38028c2e750ace15be23c7b3915d9c13a4ac99265c3627f6a0c8c8188267d32.jpg", "width": 1536, "height": 2048, "url": "https://i.sstatic.net/2vCzw9M6.jpg", "role": "reported_fault_context_candidate", "review": null, "rights_status": "unknown", "record_ids": ["diy-313310"], "source_files": ["repair-integrated-20261009\\images\\indoor-313310-0.jpg", "indoor-repair-20261009\\media\\020\\08.jpg"], "source_metadata": [{"file": "indoor-repair-20261009\\clean.json", "record": {"id": "313310-0", "question_id": 313310, "category": "door_fault", "kind": "image", "url": "https://i.sstatic.net/2vCzw9M6.jpg", "alt": "indoor latch", "source_url": "https://diy.stackexchange.com/questions/313310/front-door-latch-freezing-in-open-position-in-cold-weather", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 1536, "height": 2048, "final_url": "https://i.sstatic.net/2vCzw9M6.jpg", "local_path": "media/020/08.jpg", "sha256": "b38028c2e750ace15be23c7b3915d9c13a4ac99265c3627f6a0c8c8188267d32", "retrieved_at": "2026-10-09T08:52:59.203870+00:00", "visual_review": "contact_sheet_review_2026-10-09", "review_note": "门闩或锁具拆卸状态；卡住或结冰依据原帖，不是经验证的诊断。", "evidence_level": "reported_symptom_context"}}, {"file": "indoor-repair-20261009\\dataset.json", "record": {"id": "313310-0", "question_id": 313310, "category": "door_fault", "kind": "image", "url": "https://i.sstatic.net/2vCzw9M6.jpg", "alt": "indoor latch", "source_url": "https://diy.stackexchange.com/questions/313310/front-door-latch-freezing-in-open-position-in-cold-weather", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 1536, "height": 2048, "final_url": "https://i.sstatic.net/2vCzw9M6.jpg", "local_path": "media/020/08.jpg", "sha256": "b38028c2e750ace15be23c7b3915d9c13a4ac99265c3627f6a0c8c8188267d32", "retrieved_at": "2026-10-09T08:52:59.203870+00:00"}}, {"file": "repair-integrated-20261009\\dataset.json", "record": {"id": "indoor-313310-0", "group": "indoor", "category": "door_fault", "category_zh": "门锁与门闩异常", "title": "Front door latch freezing in \"open position\" in cold weather", "reported_symptom": "I live in Canada in a recently renovated house with tight building envelope.  I''ve noticed in cold weather, roughly -15C (5F) or below, the front door latch (will sometimes get stuck in the open position (i.e. the ''bolt'' will not come out of its hole, or will only partially return to the ''closed'' position), making it impossible to shut the door without manually pulling it out with a pair of pliers. I''ve opened up the handle and there is a fair amount of condensation on the latch mechanism.  I suspect that when I open the door, the cold end of the bolt freezes some of the water in the interior of the mechanism. The two screw holes in Figure 3 have big gaps in them so warm house air is free to go into the bore of the door. I also notice that the exterior ''thumb latch'' handle (Figure 4) seems more prone to not returning to its neutral position than the interior handle (Figure 3). I notice sometimes a bit (or a lot!) of frost accumulating in the there opening, which probably doesn''t help. Indoor humidity is 40-45% (Figure 2). I realize this is a bit higher than recommended, but its tricky to get it into the 30''s. We run the HRV ~40 minutes/hr (I''m not sure the humidistat function works on our thermostat/controller). Figure 1 Figure 2 Figure 3 Figure 4 My question How can I help prevent the latch from icing up in cold weather?  I''m especially looking for solutions at the door. I know reducing humidity will help but super low humidity will cause me other problems with wood, instruments, etc. However, if you think I''m being an idiot and just need to turn my house into a desert, that''s a valid answer too. I''ve considered: a waterproof lubricant for the door latch, but not sure what to use - I tried graphite lube but it just made a mess (as you can see in the pictures) sealing the holes in the door latch to reduce warm air flow into the door bore. replacing the exterior thumb-handle with a regular handle.", "display_label": "门锁与门闩异常", "label_basis": "reported_symptom_context", "demo_status": "待维修（演示设定）", "demo_status_is_synthetic": true, "actual_work_order": false, "diagnosis_confirmed": false, "source_url": "https://diy.stackexchange.com/questions/313310/front-door-latch-freezing-in-open-position-in-cold-weather", "image_url": "https://i.sstatic.net/2vCzw9M6.jpg", "author": "alex_danielssen", "content_license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "image_rights_status": "not_independently_verified", "source_record_file": "D:\\project\\Safescan_agent\\data\\collection-pilot\\indoor-repair-20261009\\clean.json", "source_image_path": "D:\\project\\Safescan_agent\\data\\collection-pilot\\indoor-repair-20261009\\media\\020\\08.jpg", "review_note": "门闩或锁具拆卸状态；卡住或结冰依据原帖，不是经验证的诊断。", "local_path": "images/indoor-313310-0.jpg", "sha256": "b38028c2e750ace15be23c7b3915d9c13a4ac99265c3627f6a0c8c8188267d32", "country": null}}, {"file": "indoor-repair-20261009\\media\\020\\outcomes.json", "record": {"id": "313310-0", "question_id": 313310, "category": "door_fault", "kind": "image", "url": "https://i.sstatic.net/2vCzw9M6.jpg", "alt": "indoor latch", "source_url": "https://diy.stackexchange.com/questions/313310/front-door-latch-freezing-in-open-position-in-cold-weather", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 1536, "height": 2048, "final_url": "https://i.sstatic.net/2vCzw9M6.jpg", "local_path": "08.jpg", "sha256": "b38028c2e750ace15be23c7b3915d9c13a4ac99265c3627f6a0c8c8188267d32", "retrieved_at": "2026-10-09T08:52:59.203870+00:00"}}]}') ON CONFLICT (id) DO UPDATE SET bucket=EXCLUDED.bucket, object_key=EXCLUDED.object_key, mime_type=EXCLUDED.mime_type, byte_size=EXCLUDED.byte_size, width=EXCLUDED.width, height=EXCLUDED.height, source_url=EXCLUDED.source_url, metadata=EXCLUDED.metadata;
