INSERT INTO collected_data.media_assets (id, bucket, object_key, mime_type, byte_size, width, height, source_url, metadata) VALUES ('5f78c7830c5ef9bdcf39e9aec316f2dc0a6b8e7da2c8507abb3368ec02289f1e', 'safescan-media', 'datasets/collection-20261009/images/5f78c7830c5ef9bdcf39e9aec316f2dc0a6b8e7da2c8507abb3368ec02289f1e.jpg', 'image/jpeg', 125231, 809, 762, 'https://i.sstatic.net/QM77m.jpg', '{"id": "5f78c7830c5ef9bdcf39e9aec316f2dc0a6b8e7da2c8507abb3368ec02289f1e", "path": "images/5f78c7830c5ef9bdcf39e9aec316f2dc0a6b8e7da2c8507abb3368ec02289f1e.jpg", "width": 809, "height": 762, "url": "https://i.sstatic.net/QM77m.jpg", "role": "reported_fault_context_candidate", "review": null, "rights_status": "unknown", "record_ids": ["diy-273378"], "source_files": ["repair-integrated-20261009\\images\\indoor-273378-0.jpg", "indoor-repair-20261009\\media\\020\\15.jpg"], "source_metadata": [{"file": "indoor-repair-20261009\\clean.json", "record": {"id": "273378-0", "question_id": 273378, "category": "appliance_leak", "kind": "image", "url": "https://i.sstatic.net/QM77m.jpg", "alt": "enter image description here", "source_url": "https://diy.stackexchange.com/questions/273378/leaking-washing-machine-valve-stuck", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 809, "height": 762, "final_url": "https://i.sstatic.net/QM77m.jpg", "local_path": "media/020/15.jpg", "sha256": "5f78c7830c5ef9bdcf39e9aec316f2dc0a6b8e7da2c8507abb3368ec02289f1e", "retrieved_at": "2026-10-09T08:53:13.528924+00:00", "visual_review": "contact_sheet_review_2026-10-09", "review_note": "洗衣机、软管连接或阀门照片；不能一律标成机器本体损坏。", "evidence_level": "reported_symptom_context"}}, {"file": "indoor-repair-20261009\\dataset.json", "record": {"id": "273378-0", "question_id": 273378, "category": "appliance_leak", "kind": "image", "url": "https://i.sstatic.net/QM77m.jpg", "alt": "enter image description here", "source_url": "https://diy.stackexchange.com/questions/273378/leaking-washing-machine-valve-stuck", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 809, "height": 762, "final_url": "https://i.sstatic.net/QM77m.jpg", "local_path": "media/020/15.jpg", "sha256": "5f78c7830c5ef9bdcf39e9aec316f2dc0a6b8e7da2c8507abb3368ec02289f1e", "retrieved_at": "2026-10-09T08:53:13.528924+00:00"}}, {"file": "repair-integrated-20261009\\dataset.json", "record": {"id": "indoor-273378-0", "group": "indoor", "category": "appliance_leak", "category_zh": "家电漏水", "title": "Leaking washing machine valve stuck", "reported_symptom": "I noticed both hot and cold water inlets to my washing machine were leaking in small amounts. Turning the valves off stopped the dripping. Of course, I wanted to replace the valves. I would possibly replace the cold water side myself, and have the more-coroded hot water side done by a pro. I''m having a terrible time trying to get the cold water valve off, and I''m afraid of damaging the copper pipe. Also, as snug as I secured the wrench on the valve-end, I''ve chewed some of it up. I''m trying to turn what I think is the end of the valve (the red arrow). There is NO nut (hex shape) anywhere on the other side of the threads (to the right of the red arrow) to hold on to with another wrench. I''ve sprayed rust penetrant on the valve end and threads several times, allowing some time on each application, but no luck. (I know it''s counter-clockwise.) So the questions are: Am I turning in the right spot? If 1 is yes, any ideas how to loosen the valve without damaging the pipe? (I''m really hoping to avoid using a torch, as there''s a wall very close.) Although I''m pretty sure I make no contact with the ''thing'' in the blue box. It''s now dripping when the water is turned back on. What is it? The T-handle at the top won''t budge by hand. The plastic tube coming off of it runs to the washer drain. Looks as though the other end of the T-handle might go into the pipe, though that''s a guess as I did not loosen the clamp around the pipe. (I thought that maybe this was a pressure relief mechanism, but why have it on the cold side and not on the hot side?) Thanks for any help.", "display_label": "家电漏水", "label_basis": "reported_symptom_context", "demo_status": "待维修（演示设定）", "demo_status_is_synthetic": true, "actual_work_order": false, "diagnosis_confirmed": false, "source_url": "https://diy.stackexchange.com/questions/273378/leaking-washing-machine-valve-stuck", "image_url": "https://i.sstatic.net/QM77m.jpg", "author": "Roger D", "content_license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "image_rights_status": "not_independently_verified", "source_record_file": "D:\\project\\Safescan_agent\\data\\collection-pilot\\indoor-repair-20261009\\clean.json", "source_image_path": "D:\\project\\Safescan_agent\\data\\collection-pilot\\indoor-repair-20261009\\media\\020\\15.jpg", "review_note": "洗衣机、软管连接或阀门照片；不能一律标成机器本体损坏。", "local_path": "images/indoor-273378-0.jpg", "sha256": "5f78c7830c5ef9bdcf39e9aec316f2dc0a6b8e7da2c8507abb3368ec02289f1e", "country": null}}, {"file": "indoor-repair-20261009\\media\\020\\outcomes.json", "record": {"id": "273378-0", "question_id": 273378, "category": "appliance_leak", "kind": "image", "url": "https://i.sstatic.net/QM77m.jpg", "alt": "enter image description here", "source_url": "https://diy.stackexchange.com/questions/273378/leaking-washing-machine-valve-stuck", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 809, "height": 762, "final_url": "https://i.sstatic.net/QM77m.jpg", "local_path": "15.jpg", "sha256": "5f78c7830c5ef9bdcf39e9aec316f2dc0a6b8e7da2c8507abb3368ec02289f1e", "retrieved_at": "2026-10-09T08:53:13.528924+00:00"}}]}') ON CONFLICT (id) DO UPDATE SET bucket=EXCLUDED.bucket, object_key=EXCLUDED.object_key, mime_type=EXCLUDED.mime_type, byte_size=EXCLUDED.byte_size, width=EXCLUDED.width, height=EXCLUDED.height, source_url=EXCLUDED