INSERT INTO collected_data.media_assets (id, bucket, object_key, mime_type, byte_size, width, height, source_url, metadata) VALUES ('8e9b3677be17b5ec14f939454472509791b6eed3ab54b8ac785dbae6836051cc', 'safescan-media', 'datasets/collection-20261009/images/8e9b3677be17b5ec14f939454472509791b6eed3ab54b8ac785dbae6836051cc.jpg', 'image/jpeg', 722946, 2991, 2236, 'https://i.sstatic.net/VWtgJ.jpg', '{"id": "8e9b3677be17b5ec14f939454472509791b6eed3ab54b8ac785dbae6836051cc", "path": "images/8e9b3677be17b5ec14f939454472509791b6eed3ab54b8ac785dbae6836051cc.jpg", "width": 2991, "height": 2236, "url": "https://i.sstatic.net/VWtgJ.jpg", "role": "reported_fault_context_candidate", "review": null, "rights_status": "unknown", "record_ids": ["diy-200955"], "source_files": ["used-fixtures-20261009\\media\\000\\08.jpg", "repair-integrated-20261009\\images\\indoor-200955-0.jpg"], "source_metadata": [{"file": "repair-integrated-20261009\\dataset.json", "record": {"id": "indoor-200955-0", "group": "indoor", "category": "washer_fault", "category_zh": "洗衣机异常", "title": "Washing Machine door locking/lights working, but no power to solenoid or motor", "reported_symptom": "My machine is turning on with the led''s lighting, allowing me to select and start a program, doors locking and then the counter starts to countdown as normal. But nothing else happens, no water and no motor. I have tried spin modes etc, but they are all the same. I have checked that the solenoids work when powered from an external source, But they are not receiving power from the control unit.\nThere is still meat on the motor bushes and the drum spins freely. This is my first time looking at fixing a washing machine so I don''t really know what else I can check, If there are fusees or other safety ''trips'' etc? That said, I would have thought that if that was the issue there would be an Error message showing? is there maybe a relay I can replace? or..? Any help would be greatly appreciated! Ash Machine: Electrolux / Zanussi ZWF12280W EDIT: inspired by jwh20''s comment bellow, I took a closer look at the control board. I think it might be something to do with the ''chard'' section.", "display_label": "洗衣机异常", "label_basis": "user_report_not_verified_diagnosis", "demo_status": "待维修（演示设定）", "demo_status_is_synthetic": true, "actual_work_order": false, "diagnosis_confirmed": false, "source_url": "https://diy.stackexchange.com/questions/200955/washing-machine-door-locking-lights-working-but-no-power-to-solenoid-or-motor", "image_url": "https://i.sstatic.net/VWtgJ.jpg", "author": "Ashley Reid", "content_license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "image_rights_status": "not_independently_verified", "source_record_file": "D:\\project\\Safescan_agent\\data\\collection-pilot\\used-fixtures-20261009\\dataset.json", "source_image_path": "D:\\project\\Safescan_agent\\data\\collection-pilot\\used-fixtures-20261009\\media\\000\\08.jpg", "review_note": "现场设备或部件照片；故障依据原帖，不要求照片直接展示故障。", "local_path": "images/indoor-200955-0.jpg", "sha256": "8e9b3677be17b5ec14f939454472509791b6eed3ab54b8ac785dbae6836051cc", "country": null}}, {"file": "used-fixtures-20261009\\dataset.json", "record": {"id": "200955-0", "question_id": 200955, "category": "washer_fault", "kind": "image", "url": "https://i.sstatic.net/VWtgJ.jpg", "alt": "enter image description here", "source_url": "https://diy.stackexchange.com/questions/200955/washing-machine-door-locking-lights-working-but-no-power-to-solenoid-or-motor", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 2991, "height": 2236, "final_url": "https://i.sstatic.net/VWtgJ.jpg", "local_path": "media/000/08.jpg", "sha256": "8e9b3677be17b5ec14f939454472509791b6eed3ab54b8ac785dbae6836051cc", "retrieved_at": "2026-10-09T08:58:58.305444+00:00"}}, {"file": "used-fixtures-20261009\\media\\000\\outcomes.json", "record": {"id": "200955-0", "question_id": 200955, "category": "washer_fa