INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-159660', 'Sink drain pipe leaking', '管道漏水', 'https://diy.stackexchange.com/questions/159660/sink-drain-pipe-leaking', FALSE, '{"id": "diy-159660", "name": "Sink drain pipe leaking", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "管道漏水", "source_url": "https://diy.stackexchange.com/questions/159660/sink-drain-pipe-leaking", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "Chris Walls", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "indoor-repair-20261009", "source_metadata": "indoor-repair-20261009\\dataset.json", "image_ids": ["8cc92323ae000162231f1b0961383aa27bfe16500550f60b2d4c0a1c56618cb1"], "original_record": {"question_id": 159660, "category": "pipe_leak", "category_zh": "管道漏水", "title": "Sink drain pipe leaking", "reported_symptom": "I recently replaced my bathroom sink and the new drain pipe isn''t threaded like the older one.  So instead of a connection to the P trap with a threaded male/female piece and a tightening ring, the new drain simply slides into the P trap piece.  This is where the leak is happening.  I tried to use silicone to seal the open space but if running the water on a higher pressure, or if soap is used, the leak is immediate.   What is the best way to eliminate the leak?  Help! Note: Both new and old piping is PVC.", "source_url": "https://diy.stackexchange.com/questions/159660/sink-drain-pipe-leaking", "author": "Chris Walls", "author_url": "https://diy.stackexchange.com/users/98216/chris-walls", "content_license": "CC BY-SA 4.0", "created_at_unix": 1552482834, "raw_path": "raw/pipe_leak.json", "raw_sha256": "38b104bdb79e2494cd82b2f7f1ad11c1e1defa10ab63242d781b45c5293a9ae0", "retrieved_at": "2026-10-09T08:49:22.054615+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "assets": [{"id": "159660-0", "question_id": 159660, "category": "pipe_leak", "kind": "image", "url": "https://i.sstatic.net/0ajZQ.jpg", "alt": "enter image description here", "source_url": "https://diy.stackexchange.com/questions/159660/sink-drain-pipe-leaking", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 640, "height": 480, "final_url": "https://i.sstatic.net/0ajZQ.jpg", "local_path": "media/000/00.jpg", "sha256": "8cc92323ae000162231f1b0961383aa27bfe16500550f60b2d4c0a1c56618cb1", "retrieved_at": "2026-10-09T08:52:00.102731+00:00"}]}, "image_count": 1}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
