INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-208363', 'I can’t stop a tail pipe leak after installing in bathroom sink', '管道漏水', 'https://diy.stackexchange.com/questions/208363/i-can-t-stop-a-tail-pipe-leak-after-installing-in-bathroom-sink', FALSE, '{"id": "diy-208363", "name": "I can’t stop a tail pipe leak after installing in bathroom sink", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "管道漏水", "source_url": "https://diy.stackexchange.com/questions/208363/i-can-t-stop-a-tail-pipe-leak-after-installing-in-bathroom-sink", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "Mark Z", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "indoor-repair-20261009", "source_metadata": "indoor-repair-20261009\\dataset.json", "image_ids": ["555f895813bf9903c631b396fac0505b2e046b9ae004c5690c4e3deb72f6fa5c"], "original_record": {"question_id": 208363, "category": "pipe_leak", "category_zh": "管道漏水", "title": "I can’t stop a tail pipe leak after installing in bathroom sink", "reported_symptom": "I installed a new faucet and tail pipe in a bathroom sink. It leaks where the tail pipe collar connects under the sink. I have done this type of bathroom faucet replacement probably 6 or 7 times over the years, so I know you can under tighten and over tighten the collar under the sink - the rubber gasket can get out of wack if you tighten the collar too much. But even knowimg that I can not get it to stop leaking right there. I have dismantled all of it a couple times, reapplied a rope of plumbers putty each time up top, made sure the new rubber gasket is inserted properly, tightened it down, and it still leaks. I have no other ideas and it is getting frustrating. Yes I could call a professional out but I feel like I am so close. Plus I have to do the other sink’s faucet next (it’s a double sink countertop). Any ideas?", "source_url": "https://diy.stackexchange.com/questions/208363/i-can-t-stop-a-tail-pipe-leak-after-installing-in-bathroom-sink", "author": "Mark Z", "author_url": "https://diy.stackexchange.com/users/125486/mark-z", "content_license": "CC BY-SA 4.0", "created_at_unix": 1604906715, "raw_path": "raw/pipe_leak.json", "raw_sha256": "38b104bdb79e2494cd82b2f7f1ad11c1e1defa10ab63242d781b45c5293a9ae0", "retrieved_at": "2026-10-09T08:49:22.055186+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "assets": [{"id": "208363-0", "question_id": 208363, "category": "pipe_leak", "kind": "image", "url": "https://i.sstatic.net/nXy4R.jpg", "alt": "enter image description here", "source_url": "https://diy.stackexchange.com/questions/208363/i-can-t-stop-a-tail-pipe-leak-after-installing-in-bathroom-sink", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 2100, "height": 1575, "final_url": "https://i.sstatic.net/nXy4R.jpg", "local_path": "media/000/02.jpg", "sha256": "555f895813bf9903c631b396fac0505b2e046b9ae004c5690c4e3deb72f6fa5c", "retrieved_at": "2026-10-09T08:52:05.031189+00:00"}]}, "image_count": 1}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
