INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-193273', 'Leak from the pipe in the basement that connects to kitchen sink', '管道漏水', 'https://diy.stackexchange.com/questions/193273/leak-from-the-pipe-in-the-basement-that-connects-to-kitchen-sink', FALSE, '{"id": "diy-193273", "name": "Leak from the pipe in the basement that connects to kitchen sink", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "管道漏水", "source_url": "https://diy.stackexchange.com/questions/193273/leak-from-the-pipe-in-the-basement-that-connects-to-kitchen-sink", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "mike123", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "indoor-repair-20261009", "source_metadata": "indoor-repair-20261009\\dataset.json", "image_ids": ["5075fe622facd7b3fc083e31f868242cd9644e2f2291bf45666948c4c246458c", "87cad53400e180beef0a1a21065f85340b2243928141306b4b94bfa7206534a1"], "original_record": {"question_id": 193273, "category": "pipe_leak", "category_zh": "管道漏水", "title": "Leak from the pipe in the basement that connects to kitchen sink", "reported_symptom": "Everytime kitchen sink water is used it leaks through in the basement (shown in the picture below). I wonder if that can be fixed by applying silicon around or it''s something bigger of an issue that might require professional. Update 1 I followed up on suggestions from feedback and confirmed that it''s leaking from the original place. Also tried putting pressure on the pipe to see if water can leak more. When applying pressure like this (see the second picture attached) the leak stops. That might mean that there is crack in the pipe? Silicon can be a solution albeit temporary one, right?", "source_url": "https://diy.stackexchange.com/questions/193273/leak-from-the-pipe-in-the-basement-that-connects-to-kitchen-sink", "author": "mike123", "author_url": "https://diy.stackexchange.com/users/117544/mike123", "content_license": "CC BY-SA 4.0", "created_at_unix": 1590023005, "raw_path": "raw/pipe_leak.json", "raw_sha256": "38b104bdb79e2494cd82b2f7f1ad11c1e1defa10ab63242d781b45c5293a9ae0", "retrieved_at": "2026-10-09T08:49:22.056096+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "assets": [{"id": "193273-0", "question_id": 193273, "category": "pipe_leak", "kind": "image", "url": "https://i.sstatic.net/lfvK5.png", "alt": "enter image description here", "source_url": "https://diy.stackexchange.com/questions/193273/leak-from-the-pipe-in-the-basement-that-connects-to-kitchen-sink", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 505, "height": 630, "final_url": "https://i.sstatic.net/lfvK5.png", "local_path": "media/000/03.png", "sha256": "5075fe622facd7b3fc083e31f868242cd9644e2f2291bf45666948c4c246458c", "retrieved_at": "2026-10-09T08:52:06.220195+00:00"}, {"id": "193273-1", "question_id": 193273, "category": "pipe_leak", "kind": "image", "url": "https://i.sstatic.net/2X6tb.png", "alt": "enter image description here", "source_url": "https://diy.stackexchange.com/questions/193273/leak-from-the-pipe-in-the-basement-that-connects-to-kitchen-sink", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 546, "height": 569, "final_url": "https://i.sstatic.net/2X6tb.png", "local_path": "media/000/04.png", "sha256": "87cad53400e180beef0a1a21065f85340b2243928141306b4b94bfa7206534a1", "retrieved_at": "2026-10-09T08:52:09.412710+00:00"}]}, "image_count": 2}') ON CONFLICT (id) DO UPDATE SET n