INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-162279', 'Should I attempt to fix a sink leak myself?', '管道漏水', 'https://diy.stackexchange.com/questions/162279/should-i-attempt-to-fix-a-sink-leak-myself', FALSE, '{"id": "diy-162279", "name": "Should I attempt to fix a sink leak myself?", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "管道漏水", "source_url": "https://diy.stackexchange.com/questions/162279/should-i-attempt-to-fix-a-sink-leak-myself", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "mafrosis", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "indoor-repair-20261009", "source_metadata": "indoor-repair-20261009\\dataset.json", "image_ids": ["748cf4ce765f5010e719ffea725414f9e1ae60aa6160ee7ef4b18707fe0748c8"], "original_record": {"question_id": 162279, "category": "pipe_leak", "category_zh": "管道漏水", "title": "Should I attempt to fix a sink leak myself?", "reported_symptom": "I have a slow leak under my kitchen sink, in what I think is the top-most screw thread in the photo below. It leaks when the sink is full. EDIT: specifically, I think the leak is between the gray sink pipe and the off-white pipe right at the top. I am very practical (carpentry and such) but have zero plumbing experience. Even with sinks. Can I \"just\" buy some parts and connect them up? Like water lego Thanks!", "source_url": "https://diy.stackexchange.com/questions/162279/should-i-attempt-to-fix-a-sink-leak-myself", "author": "mafrosis", "author_url": "https://diy.stackexchange.com/users/99624/mafrosis", "content_license": "CC BY-SA 4.0", "created_at_unix": 1555538431, "raw_path": "raw/pipe_leak.json", "raw_sha256": "38b104bdb79e2494cd82b2f7f1ad11c1e1defa10ab63242d781b45c5293a9ae0", "retrieved_at": "2026-10-09T08:49:22.056348+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "assets": [{"id": "162279-0", "question_id": 162279, "category": "pipe_leak", "kind": "image", "url": "https://i.sstatic.net/WjYMS.jpg", "alt": "enter image description here", "source_url": "https://diy.stackexchange.com/questions/162279/should-i-attempt-to-fix-a-sink-leak-myself", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 1512, "height": 2016, "final_url": "https://i.sstatic.net/WjYMS.jpg", "local_path": "media/000/05.jpg", "sha256": "748cf4ce765f5010e719ffea725414f9e1ae60aa6160ee7ef4b18707fe0748c8", "retrieved_at": "2026-10-09T08:52:10.241206+00:00"}]}, "image_count": 1}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
