INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-183907', 'Double sink clogged in mobile home', '排水堵塞', 'https://diy.stackexchange.com/questions/183907/double-sink-clogged-in-mobile-home', FALSE, '{"id": "diy-183907", "name": "Double sink clogged in mobile home", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "排水堵塞", "source_url": "https://diy.stackexchange.com/questions/183907/double-sink-clogged-in-mobile-home", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "Chelsea", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "indoor-repair-20261009", "source_metadata": "indoor-repair-20261009\\dataset.json", "image_ids": ["71583f4c9b3c65a2aebc460b32f04414eefdc715616a62618af08b6db6c7ef69", "59efe1361ab7e016c42817d757adad3b5f8ddd1fd9bc2c14ce6bf7fe8238189b"], "original_record": {"question_id": 183907, "category": "drain_blockage", "category_zh": "排水堵塞", "title": "Double sink clogged in mobile home", "reported_symptom": "Was working through a clogged sink yesterday, had a partial flow, went to my parents for a bit, came back to find husband and roommate had decided to take it into their own hands, got some bleach smelling chemical and a plunger and there was no longer a partial flow. I should also mention we have a septic tank. Watched this video: https://youtu.be/JeurinbyqhQ Removed pea trap and confirmed clog isn’t there. The rest of my pipes differ from the video so I’m not sure how much I should remove. I was able to get a drain snake in the horizontal part but was unable to go down. There is a little thing near the bottom, black plug with a square twist thing. Not sure if it okay to remove that. Update, took the access plug thing out. Clog seems to be below that. Post two snakes. First snake made the water go down to where I could just see it. After second snake I can’t see the water. Our plumber previously gave us some Bio-Clean drain cleaner. Going to close everything up and treat the pipes with that, see where we stand after a few hours of that sitting.", "source_url": "https://diy.stackexchange.com/questions/183907/double-sink-clogged-in-mobile-home", "author": "Chelsea", "author_url": "https://diy.stackexchange.com/users/109692/chelsea", "content_license": "CC BY-SA 4.0", "created_at_unix": 1580666513, "raw_path": "raw/drain_blockage.json", "raw_sha256": "6d054127911613a0027a81a191aed2520b6b043ec5b5c654524e76c5c6108864", "retrieved_at": "2026-10-09T08:49:23.422815+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "assets": [{"id": "183907-0", "question_id": 183907, "category": "drain_blockage", "kind": "image", "url": "https://i.sstatic.net/xblgj.jpg", "alt": "sink picture ", "source_url": "https://diy.stackexchange.com/questions/183907/double-sink-clogged-in-mobile-home", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 640, "height": 480, "final_url": "https://i.sstatic.net/xblgj.jpg", "local_path": "media/000/06.jpg", "sha256": "71583f4c9b3c65a2aebc460b32f04414eefdc715616a62618af08b6db6c7ef69", "retrieved_at": "2026-10-09T08:52:12.809504+00:00"}, {"id": "183907-1", "question_id": 183907, "category": "drain_blockage", "kind": "image", "url": "https://i.sstatic.net/pyIKm.jpg", "alt": "circle with square knob thing", "source_url": "https://diy.stackexchange.com/questions/183907/double-sink-clogged-in-mobile-home", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 640, "height": 480, "final_url": "https://i.sstatic.net/pyIKm.jpg", "local_path": "media/000/07.jpg", "sha256": "59efe1361ab7e016c42817d757adad3b5f8ddd1fd9bc2c14ce6bf7fe8238189b", "retrieved_at": "2026-10-09T08:52:14.070889+00:00"}]}, "image_count": 2}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
