INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-100038', 'Sink clogged completely when using NaOH drain cleaner', '排水堵塞', 'https://diy.stackexchange.com/questions/100038/sink-clogged-completely-when-using-naoh-drain-cleaner', FALSE, '{"id": "diy-100038", "name": "Sink clogged completely when using NaOH drain cleaner", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "排水堵塞", "source_url": "https://diy.stackexchange.com/questions/100038/sink-clogged-completely-when-using-naoh-drain-cleaner", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "Petko.Maria.John", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "indoor-repair-20261009", "source_metadata": "indoor-repair-20261009\\dataset.json", "image_ids": ["bf3ed2112b9287f5aa8f6be43f318a5598cf0d58adc960bbe50e21d03ca614af", "ec9f68462398bdf81d12570d233cc6d5638e39ebda77975c1dada86de168111c"], "original_record": {"question_id": 100038, "category": "drain_blockage", "category_zh": "排水堵塞", "title": "Sink clogged completely when using NaOH drain cleaner", "reported_symptom": "I used a drain cleaner containing sodium hydroxide (NaOH) to unclog it. I followed the drain cleaner''s instructions to the letter: pour the NaOH into the pipe entrance. pour hot water. As soon as I started pouring hot water, it started pooling. No water would pass through. The sink was completely clogged now, because the NaOH formed a solid \"bathtub plug\" inside the pipe! (I could see solid white NaOH) Pouring more water had no effect, so I carefully threw citric acid grains (a weak acid, contained in lemons), hoping the acid would react with the base (NaOH). Initially, the acid reacted with the NaOH (I could see bubbles coming out), but then it stopped completely. WARNING : Acid and NaOH reactions can be very violent . In my case there was enough water to act as a heat-sink preventing boiling and splashing, and I was adding acid slowly. I can''t emphasize enough how dangerous NaOH is. Use full face protection and gloves, otherwise you could go blind or get severe skin burns . I don''t want to open the pipes (if flow is restored it could splash NaOH solution on me). Is there any other way to safely unclog the NaOH? What exactly happened? Why did NaOH block the pipe completely, and why did the acid become ineffective after a while? Sidenote on why I did it: My partially clogged kitchen sink would allow small amounts of water to pass through the pipe. I''ve been using a plunger when it was getting clogged (snake was ineffective). A plumber had told me in the past, that the problem is deep inside the wall (about 3 meters into the pipe) and is very hard to fix. He also suggested using NaOH a couple of times a year to keep it clean. Top view and side view respectively:", "source_url": "https://diy.stackexchange.com/questions/100038/sink-clogged-completely-when-using-naoh-drain-cleaner", "author": "Petko.Maria.John", "author_url": "https://diy.stackexchange.com/users/60242/petko-maria-john", "content_license": "CC BY-SA 4.0", "created_at_unix": 1474973960, "raw_path": "raw/drain_blockage.json", "raw_sha256": "6d054127911613a0027a81a191aed2520b6b043ec5b5c654524e76c5c6108864", "retrieved_at": "2026-10-09T08:49:23.423506+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "assets": [{"id": "100038-0", "question_id": 100038, "category": "drain_blockage", "kind": "image", "url": "https://i.sstatic.net/GeVh6.png", "alt": "enter image description here", "source_url": "https://diy.stackexchange.com/questions/100038/sink-clogged-completely-when-using-naoh-drain-cleaner", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 242, "height": 177, "final_url": "https://i.sstatic.net/GeVh6.png", "local_path": "media/000/08.png", "sha256": "bf3ed2112b9287f5aa8f6be43f318a5598cf0d58adc960bbe50e21d03ca614af", "retrieved_at": "2026-10-09T08:52:15.892647+00:00"}, {"id": "100038-1", "question_id": 100038, "category": "drain_blockage", "kind": "image", "url": "https://i.sstatic.net/jOeY2.png", "alt": "enter image description here", "source_url": "https://diy.stackexchange.com/questions/100038/sink-clogged-completely-when-using-naoh-drain-cleaner", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 224, "height": 186, "final_url": "https://i.sstatic.net/jOeY2.png", "local_path": "media/000/09.png", "sha256": "ec9f68462398bdf81d12570d233cc6d5638e39ebda77975c1dada86de168111c", "retrieved_at": "2026-10-09T08:52:17.892622+00:00"}]}, "image_count": 2}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
