INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-278029', 'My sink is not clogged but water does not drain', '排水堵塞', 'https://diy.stackexchange.com/questions/278029/my-sink-is-not-clogged-but-water-does-not-drain', FALSE, '{"id": "diy-278029", "name": "My sink is not clogged but water does not drain", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "排水堵塞", "source_url": "https://diy.stackexchange.com/questions/278029/my-sink-is-not-clogged-but-water-does-not-drain", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "mwoua", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "indoor-repair-20261009", "source_metadata": "indoor-repair-20261009\\dataset.json", "image_ids": ["8b81b9e3eaa693be551cddee1eaf54629a9994a30070114b5d9768f95cade0d6", "b18ced4491cdf9b4552a30d06ce2825d4be82f854ef772ef42dc1525cba4f9e7"], "original_record": {"question_id": 278029, "category": "drain_blockage", "category_zh": "排水堵塞", "title": "My sink is not clogged but water does not drain", "reported_symptom": "Our kitchen sink (which is like 2 weeks old) is clogging up... and it''s really weird, because I can''t find a single (physical) clog. When you fill up a basin (let''s say you put in 2 liters) and open the drain of the sink, there''s maybe like 0.5 liters flowing perfectly, then after a certain point, it gurgles and suddenly stops draining. The water then flows in slow motion... At first I thought it was a physical clog. I unscrewed the siphon but nothing, it''s as good as new (two weeks old at the same time). When I pour water into the tub with the siphon disconnected from the discharge, everything just flows through the siphon and goes into the bucket without a hitch. So the siphon isn''t the problem. So I thought the clog was further down, in the discharge. I put some destop in, went in with a ferret (plumbing snake in english? Not sure), but nothing. The 5m ferret went through without a hitch (normally I should already be in the communal dump after 5m). The ferret comes out clean. It''s really like there''s nothing there at all. Then if I empty a 3-liter bucket directly into the discharge (the place where it becomes vertical on the photo under the sink) there''s no problem, everything flows normally, it doesn''t clog up or anything. So the physical clog seems to be ruled out... But when I connect the two parts, the siphon and the drain... it doesn''t flow. I tried pouring 3 liters into the drain (I looked with a camera afterwards and the vertical part was totally empty) then immediately afterwards, connecting the sink and putting 3 liters into the tray and after not even 0.5l it stopped flowing. So the problem seems to be the layout under the sink... I confess I don''t understand. Maybe a suction/air pocket/vacuum thing going on... Any ideas? Further info: originally, the sink was at the place where the pipes go into the ground. We''ve extended that further to the right.  The slope between the new position of the sink and the previous position is like a vertical drop of about 7 cm for 1.60m horizontally. So in my opinion, this is plenty enough. (The plumber wanted to do it in the ground, with like 2 cm of slope so I guess this should be enough) the flexible grey pipe you see under the sink is a dishwasher\nsee also figures Update 1: I tried what you suggested... but it does not seem to help much. It feels like it still helps a bit. I feel like there''s more water that flows before it stops. But i''m not sure... Here is what I added (see figure) Would it also make sense to put a vent here? Since after that point, there is still like 2 meters to the left (I think??) Before the common discharge.", "source_url": "https://diy.stackexchange.com/questions/278029/my-sink-is-not-clogged-but-water-does-not-drain", "author": "mwoua", "author_url": "https://diy.stackexchange.com/users/170975/mwoua", "content_license": "CC BY-SA 4.0", "created_at_unix": 1690631967, "raw_path": "raw/drain_blockage.json", "raw_sha256": "6d054127911613a0027a81a191aed2520b6b043ec5b5c654524e76c5c6108864", "retrieved_at": "2026-10-09T08:49:23.424796+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "assets": [{"id": "278029-0", "question_id": 278029, "category": "drain_blockage", "kind": "image", "url": "https://i.sstatic.net/AfOu6.jpg", "alt": "first figure under the sink", "source_url": "https://diy.stackexchange.com/questions/278029/my-sink-is-not-clogged-but-water-does-not-drain", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 1079, "height": 1424, "final_url": "https://i.sstatic.net/AfOu6.jpg", "local_path": "media/000/10.jpg", "sha256": "8b81b9e3eaa693be551cddee1eaf54629a9994a30070114b5d9768f95cade0d6", "retrieved_at": "2026-10-09T08:52:19.691046+00:00"}, {"id": "278029-1", "question_id": 278029, "category": "drain_blockage", "kind": "image", "url": "https://i.sstatic.net/ftTmu.jpg", "alt": "second figure under the sink", "source_url": "https://diy.stackexchange.com/questions/278029/my-sink-is-not-clogged-but-water-does-not-drain", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 1080, "height": 812, "final_url": "https://i.sstatic.net/ftTmu.jpg", "local_path": "media/000/11.jpg", "sha256": "b18ced4491cdf9b4552a30d06ce2825d4be82f854ef772ef42dc1525cba4f9e7", "retrieved_at": "2026-10-09T08:52:21.701460+00:00"}]}, "image_count": 2}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
