INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-227947', 'Replacement light fixture not working', '灯具异常', 'https://diy.stackexchange.com/questions/227947/replacement-light-fixture-not-working', FALSE, '{"id": "diy-227947", "name": "Replacement light fixture not working", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "灯具异常", "source_url": "https://diy.stackexchange.com/questions/227947/replacement-light-fixture-not-working", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "Blake", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "indoor-repair-20261009", "source_metadata": "indoor-repair-20261009\\dataset.json", "image_ids": ["9a5c2368bd7b62808659a149f7a45656efb4f1d32d045f1d71d5d4e1fe319efc", "ce77a2d382b660ed95fe16cd899d7973a4fd27489d7c7b60d0538a1e42eb7ccb"], "original_record": {"question_id": 227947, "category": "light_fault", "category_zh": "灯具异常", "title": "Replacement light fixture not working", "reported_symptom": "I have a replacement kitchen led light fixture that is not turning on. Power is there: multimeter shows 121.6 at fixture.  Previous fixture obviously worked. There are two three-way switches for the fixture. I believe that I''ve wired correctly. I''ve tried two led fixtures. Critique as needed. Do I need to supply more info? Thank you.", "source_url": "https://diy.stackexchange.com/questions/227947/replacement-light-fixture-not-working", "author": "Blake", "author_url": "https://diy.stackexchange.com/users/137286/blake", "content_license": "CC BY-SA 4.0", "created_at_unix": 1624653860, "raw_path": "raw/light_fault.json", "raw_sha256": "e954a2dfdbdff96b4a825555c87cfcd646f75bbcc91572c455403ae08d461b3b", "retrieved_at": "2026-10-09T08:49:25.879357+00:00", "evidence_level": 