INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-152547', 'Outdoor light fixture not working', '灯具异常', 'https://diy.stackexchange.com/questions/152547/outdoor-light-fixture-not-working', FALSE, '{"id": "diy-152547", "name": "Outdoor light fixture not working", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "灯具异常", "source_url": "https://diy.stackexchange.com/questions/152547/outdoor-light-fixture-not-working", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "Dave", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "indoor-repair-20261009", "source_metadata": "indoor-repair-20261009\\dataset.json", "image_ids": ["2b704c0b47a3401dfaeed5eaafb9edf05be2100d37257e29feffc3390b67ebaa", "c6abd2e83425d7ba725e74b29f85aaebdafac5d691cbf29a16668b937ca85138"], "original_record": {"question_id": 152547, "category": "light_fault", "category_zh": "灯具异常", "title": "Outdoor light fixture not working", "reported_symptom": "I am a newbie with anything electrical so please forgive my ignorance. All of a sudden, my front porch light fixture stopped working. Changing the light bulb didn’t work so I’m trying to figure out if it’s the fixture, the switch or the wiring. I tried installing a new fixture but got a pop and flash and it didn’t work (it’s possible I connected it wrong since I was having trouble getting the wires connected with the wire nuts). So I just put the old fixture back in for now (nothing looks corroded on the fixture). The box that contains the switch for the exterior light also contains a 3 way switch for my foyer light. The only thing i noticed on the switch is that the ground wasn’t connected- is that an issue? I just replaced the switch (hot, neutral and ground) and bought a multimeter. When I test between the hot and the ground on the new switch, I’m getting 120V. When I test between what I believe to be the neutral and the ground when switch is off I get 0...when switch is on, it reads 120V. When I test between the neutral and the hot, I’m always seeing 0V. I thought this was odd- isn’t there supposed to be voltage when touching the probes to the neutral and hot? Can someone clarify this for me? Thanks in advance. Should I turn off the breaker, pull off the fixture outside and flip the breaker back on and test the wires outside to see if it’s making it outside?", "source_url": "https://diy.stackexchange.com/questions/152547/outdoor-light-fixture-not-working", "author": "Dave", "author_url": "https://diy.stackexchange.com/users/94198/dave", "content_license": "CC BY-SA 4.0", "created_at_unix": 1544626094, "raw_path": "raw/light_fault.json", "raw_sha256": "e954a2dfdbdff96b4a825555c87cfcd646f75bbcc91572c455403ae08d461b3b", "retrieved_at": "2026-10-09T08:49:25.879619+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "assets": [{"id": "152547-0", "question_id": 152547, "category": "light_fault", "kind": "image", "url": "https://i.sstatic.net/ACZF4.jpg", "alt": "enter image description here", "source_url": "https://diy.stackexchange.com/questions/152547/outdoor-light-fixture-not-working", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 4032, "height": 3024, "final_url": "https://i.sstatic.net/ACZF4.jpg", "local_path": "media/000/14.jpg", "sha256": "2b704c0b47a3401dfaeed5eaafb9edf05be2100d37257e29feffc3390b67ebaa", "retrieved_at": "2026-10-09T08:52:29.337401+00:00"}, {"id": "152547-1", "question_id": 152547, "category": "light_fault", "kind": "image", "url": "https://i.sstatic.net/GBOu3.jpg", "alt": "enter image description here", "source_url": "https://diy.stackexchange.com/questions/152547/outdoor-light-fixture-not-working", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 4032, "height": 3024, "final_url": "https://i.sstatic.net/GBOu3.jpg", "local_path": "media/000/15.jpg", "sha256": "c6abd2e83425d7ba725e74b29f85aaebdafac5d691cbf29a16668b937ca85138", "retrieved_at": "2026-10-09T08:52:31.068747+00:00"}]}, "image_count": 2}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
