INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-259875', 'Why so many wires in my old light fixture?', '灯具异常', 'https://diy.stackexchange.com/questions/259875/why-so-many-wires-in-my-old-light-fixture', FALSE, '{"id": "diy-259875", "name": "Why so many wires in my old light fixture?", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "灯具异常", "source_url": "https://diy.stackexchange.com/questions/259875/why-so-many-wires-in-my-old-light-fixture", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "Kevin", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "indoor-repair-20261009", "source_metadata": "indoor-repair-20261009\\dataset.json", "image_ids": ["ee142b7125810e53c3e52d00eb11375ca943b8682548936713e717c3d4f0269a", "88aaad234e93adb6a3241629edc4a36710f038d9c2c8734277c021b57d127781"], "original_record": {"question_id": 259875, "category": "light_fault", "category_zh": "灯具异常", "title": "Why so many wires in my old light fixture?", "reported_symptom": "My old light fixture not working so I took it apart and will get a replacement. Then I noticed so many wires! Then I cut all the wires and now have this: After I cut it, I noticed other light fixtures nearby are not working.. I plan to get a replacement fixture, but a different type, I''m not sure how I would connect these wires, as there''s 3 sets of each except brown. Edit:\nAdded photo of bottom part where brown connects", "source_url": "https://diy.stackexchange.com/questions/259875/why-so-many-wires-in-my-old-light-fixture", "author": "Kevin", "author_url": "https://diy.stackexchange.com/users/158562/kevin", "content_license": "CC BY-SA 4.0", "created_at_unix": 1667507325, "raw_path": "raw/light_fault.json", "raw_sha256": "e954a2dfdbdff96b4a825555c87cfcd646f75bbcc91572c455403ae08d461b3b", "retrieved_at": "2026-10-09T08:49:25.880269+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "assets": [{"id": "259875-0", "question_id": 259875, "category": "light_fault", "kind": "image", "url": "https://i.sstatic.net/5Cfbt.jpg", "alt": "fixture taken apart", "source_url": "https://diy.stackexchange.com/questions/259875/why-so-many-wires-in-my-old-light-fixture", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 839, "height": 1393, "final_url": "https://i.sstatic.net/5Cfbt.jpg", "local_path": "media/000/16.jpg", "sha256": "ee142b7125810e53c3e52d00eb11375ca943b8682548936713e717c3d4f0269a", "retrieved_at": "2026-10-09T08:52:32.742157+00:00"}, {"id": "259875-1", "question_id": 259875, "category": "light_fault", "kind": "image", "url": "https://i.sstatic.net/H6G67.jpg", "alt": "wires", "source_url": "https://diy.stackexchange.com/questions/259875/why-so-many-wires-in-my-old-light-fixture", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 988, "height": 1181, "final_url": "https://i.sstatic.net/H6G67.jpg", "local_path": "media/000/17.jpg", "sha256": "88aaad234e93adb6a3241629edc4a36710f038d9c2c8734277c021b57d127781", "retrieved_at": "2026-10-09T08:52:34.066274+00:00"}]}, "image_count": 2}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
