INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-105956', '220 outlet burnt caused other outlets to go out breaker didn''t trip', '插座损伤', 'https://diy.stackexchange.com/questions/105956/220-outlet-burnt-caused-other-outlets-to-go-out-breaker-didnt-trip', FALSE, '{"id": "diy-105956", "name": "220 outlet burnt caused other outlets to go out breaker didn''t trip", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "插座损伤", "source_url": "https://diy.stackexchange.com/questions/105956/220-outlet-burnt-caused-other-outlets-to-go-out-breaker-didnt-trip", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "Tabitha L Hughes", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/", "notes": null, "source_batch": "indoor-repair-20261009", "source_metadata": "indoor-repair-20261009\\dataset.json", "image_ids": ["39b514154163a02b151c6394503f37446ce032f0b4216bc9bbe720b2967fe5f3", "cf9f3cf0d8aab3d9aaa33f6bb6e4c7c25a89592ae035da87b75e8fdb6df70dac"], "original_record": {"question_id": 105956, "category": "socket_damage", "category_zh": "插座损伤", "title": "220 outlet burnt caused other outlets to go out breaker didn''t trip", "reported_symptom": "A outlet in LR was plugged in but not in use burnt up as seen in pictures. Many other outlets and porch light went out also. The breaker didn''t trip. By the looks of it I think it is copper. I cleaned out and wrapped the two corroded non black but burnt wires with electrical tape and replaced with a new outlet. Everything turned back on. I want to know if I should have it checked by an electrician to be safe and make sure the wire didn''t burn further up in the cloth stuff that it is coming out of. I didn''t pull it out or cut any but one small burnt piece off.", "source_url": "https://diy.stackexchange.com/questions/105956/220-outlet-burnt-caused-other-outlets-to-go-out-breaker-didnt-trip", "author": "Tabitha L Hughes", "author_url": "https://diy.stackexchange.com/users/64794/tabitha-l-hughes", "content_license": "CC BY-SA 3.0", "created_at_unix": 1483765532, "raw_path": "raw/socket_damage.json", "raw_sha256": "21ef6eab9883609a2a613023f295c620983b93718600babc45c4a178e7a7f9b2", "retrieved_at": "2026-10-09T08:49:27.394343+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/3.0/", "assets": [{"id": "105956-0", "question_id": 105956, "category": "socket_damage", "kind": "image", "url": "https://i.sstatic.net/83oDD.jpg", "alt": "enter image description here", "source_url": "https://diy.stackexchange.com/questions/105956/220-outlet-burnt-caused-other-outlets-to-go-out-breaker-didnt-trip", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 3024, "height": 4032, "final_url": "https://i.sstatic.net/83oDD.jpg", "local_path": "media/000/18.jpg", "sha256": "39b514154163a02b151c6394503f37446ce032f0b4216bc9bbe720b2967fe5f3", "retrieved_at": "2026-10-09T08:52:37.541767+00:00"}, {"id": "105956-1", "question_id": 105956, "category": "socket_damage", "kind": "image", "url": "https://i.sstatic.net/sH6K7.jpg", "alt": "enter image description here", "source_url": "https://diy.stackexchange.com/questions/105956/220-outlet-burnt-caused-other-outlets-to-go-out-breaker-didnt-trip", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 3306, "height": 2480, "final_url": "https://i.sstatic.net/sH6K7.jpg", "local_path": "media/000/19.jpg", "sha256": "cf9f3cf0d8aab3d9aaa33f6bb6e4c7c25a89592ae035da87b75e8fdb6df70dac", "retrieved_at": "2026-10-09T08:52:38.992462+00:00"}]}, "image_coun