INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-184717', 'Can a cooking oil spill-over cause a burnt-out outlet?', '插座损伤', 'https://diy.stackexchange.com/questions/184717/can-a-cooking-oil-spill-over-cause-a-burnt-out-outlet', FALSE, '{"id": "diy-184717", "name": "Can a cooking oil spill-over cause a burnt-out outlet?", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "插座损伤", "source_url": "https://diy.stackexchange.com/questions/184717/can-a-cooking-oil-spill-over-cause-a-burnt-out-outlet", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "ginjaemocoes", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "indoor-repair-20261009", "source_metadata": "indoor-repair-20261009\\dataset.json", "image_ids": ["5edbd8fa7c2751bdd13105c463a0ba281fa59e6e80c28312de9fe2c8c1a72980", "4cf9b6fce5e3ea7fbae5c60a10058aa91f1518262798d8b4362b974f045d4b7d"], "original_record": {"question_id": 184717, "category": "socket_damage", "category_zh": "插座损伤", "title": "Can a cooking oil spill-over cause a burnt-out outlet?", "reported_symptom": "A cooking stove with electricity and natural gas has been in place for 20 years. Last month I did deep frying, some of the oil went overboard, touched the electric plate, and some of it instantly vaporized into smoke. The oil also left a definite stain on the electric plate. Note that I didn''t smell anything burned, and that the electric plate and cooktop was 1 meter from the power plug. I didn''t use the cooktop for a month and yesterday, when I turned on an oven daisy-chained to the same outlet, the house circuit breaker went off and I smelled something burned, which I then identified as burnt plastic. The outlet was burnt-out along with the electric plug of the cooktop: (I found it hard to take a good picture because the burnt area is the blackest of the black.) I did not find any residue of oil near the outlet. The cooktop has been in place for many years in an area by the seaside with much salt, humidity (up to 80%), so metal often corrodes and rusts. Could cooking oil cause the outlet to arc and burn out? If not, what is the most likely cause? Update Here is a photo of the house''s electric panel. The tripped switch was third from the top left:", "source_url": "https://diy.stackexchange.com/questions/184717/can-a-cooking-oil-spill-over-cause-a-burnt-out-outlet", "author": "ginjaemocoes", "author_url": "https://diy.stackexchange.com/users/99311/ginjaemocoes", "content_license": "CC BY-SA 4.0", "created_at_unix": 1581678553, "raw_path": "raw/socket_damage.json", "raw_sha256": "21ef6eab9883609a2a613023f295c620983b93718600babc45c4a178e7a7f9b2", "retrieved_at": "2026-10-09T08:49:27.394938+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "assets": [{"id": "184717-0", "question_id": 184717, "category": "socket_damage", "kind": "image", "url": "https://i.sstatic.net/YmAiJ.jpg", "alt": "Burn-out outlet and plug", "source_url": "https://diy.stackexchange.com/questions/184717/can-a-cooking-oil-spill-over-cause-a-burnt-out-outlet", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 600, "height": 318, "final_url": "https://i.sstatic.net/YmAiJ.jpg", "local_path": "media/020/01.jpg", "sha256": "5edbd8fa7c2751bdd13105c463a0ba281fa59e6e80c28312de9fe2c8c1a72980", "retrieved_at": "2026-10-09T08:52:44.780994+00:00"}, {"id": "184717-1", "question_id": 184717, "category": "socket_damage", "kind": "image", "url": "https://i.sstatic.net/4uQZw.jpg", "alt": "Burnt-out plug", "source_url": "https://diy.stackexchange.com/questions/184717/can-a-cooking-oil-spill-over-cause-a-burnt-out-outlet", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 600, "height": 500, "final_url": "https://i.sstatic.net/4uQZw.jpg", "local_path": "media/020/02.jpg", "sha256": "4cf9b6fce5e3ea7fbae5c60a10058aa91f1518262798d8b4362b974f045d4b7d", "retrieved_at": "2026-10-09T08:52:46.761847+00:00"}]}, "image_count": 2}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
