"country": null, "license_url": "https://creativecommons.org/licenses/by-sa/3.0/", "assets": [{"id": "77410-0", "question_id": 77410, "category": "socket_damage", "kind": "image", "url": "https://i.sstatic.net/aUb1T.jpg", "alt": "burnt wires", "source_url": "https://diy.stackexchange.com/questions/77410/burnt-sheathing-behind-outlet", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 3264, "height": 2448, "final_url": "https://i.sstatic.net/aUb1T.jpg", "local_path": "media/020/03.jpg", "sha256": "0aee4acdb32acfb1cb0ed271ddad2b8de108edf57c9faceca00445918fb94645", "retrieved_at": "2026-10-09T08:52:49.180654+00:00"}]}, "image_count": 1}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
