INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-132007', 'Latch bolt stuck inside door jamb', '门锁与门闩异常', 'https://diy.stackexchange.com/questions/132007/latch-bolt-stuck-inside-door-jamb', FALSE, '{"id": "diy-132007", "name": "Latch bolt stuck inside door jamb", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "门锁与门闩异常", "source_url": "https://diy.stackexchange.com/questions/132007/latch-bolt-stuck-inside-door-jamb", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "Nancy", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/", "notes": null, "source_batch": "indoor-repair-20261009", "source_metadata": "indoor-repair-20261009\\dataset.json", "image_ids": ["5d6e583173388273f3459d9fb5bbfddad9accce8b2502a74bcc5eb9d0b43e1c0", "7051b1802fabea03f84fe72d625ed6f937a77b8fd0632c8b56f87eb6a9be88a3"], "original_record": {"question_id": 132007, "category": "door_fault", "category_zh": "门锁与门闩异常", "title": "Latch bolt stuck inside door jamb", "reported_symptom": "[latch bolt still in door jamb The latch bolt for my exterior door is stuck inside the door jamb. I have removed both door handles, but can''t get the door open to get at the latch plate or strike plate. Short of taking the entire door off the hinges (it''s 10 degrees in MN...), other suggestions? I believe it''s a Kwikset Titan lock.", "source_url": "https://diy.stackexchange.com/questions/132007/latch-bolt-stuck-inside-door-jamb", "author": "Nancy", "author_url": "https://diy.stackexchange.com/users/81050/nancy", "content_license": "CC BY-SA 3.0", "created_at_unix": 1517262081, "raw_path": "raw/door_fault.json", "raw_sha256": "780531b2dc2faab6006c729b46d0bb48bef2d6f7ef15d3e2df908227a295e62c", "retrieved_at": "2026-10-09T08:49:29.393344+00:00", "evidence_level": "user_report_with_a