INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-275941', 'Frozen Kwikset door latch', '门锁与门闩异常', 'https://diy.stackexchange.com/questions/275941/frozen-kwikset-door-latch', FALSE, '{"id": "diy-275941", "name": "Frozen Kwikset door latch", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "门锁与门闩异常", "source_url": "https://diy.stackexchange.com/questions/275941/frozen-kwikset-door-latch", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "Bob OC DIY", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "indoor-repair-20261009", "source_metadata": "indoor-repair-20261009\\dataset.json", "image_ids": ["43e2b6c0315d5836f1329a54544e698b2367e599e1cc0413acd77078e5d8464d", "e603aecee295cb1389fe3bad3afc4a3fb908280d9d6b6c19ba8fb11fcc56ab18"], "original_record": {"question_id": 275941, "category": "door_fault", "category_zh": "门锁与门闩异常", "title": "Frozen Kwikset door latch", "reported_symptom": "I was having trouble with this door getting stuck shut, and now it is firmly frozen shut. This is just a standard latch, not a deadbolt. I took the knob off, and that does not help. How do I get this door open?", "source_url": "https://diy.stackexchange.com/questions/275941/frozen-kwikset-door-latch", "author": "Bob OC DIY", "author_url": "https://diy.stackexchange.com/users/142769/bob-oc-diy", "content_license": "CC BY-SA 4.0", "created_at_unix": 1688846850, "raw_path": "raw/door_fault.json", "raw_sha256": "780531b2dc2faab6006c729b46d0bb48bef2d6f7ef15d3e2df908227a295e62c", "retrieved_at": "2026-10-09T08:49:29.393566+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "assets": [{"id": "275941-0", "question_id": 275941, "category": "door_fault", "kind": "image", "url": "https://i.sstatic.net/jMvOH.jpg", "alt": "inside view", "source_url": "https://diy.stackexchange.com/questions/275941/frozen-kwikset-door-latch", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 1512, "height": 2016, "final_url": "https://i.sstatic.net/jMvOH.jpg", "local_path": "media/020/06.jpg", "sha256": "43e2b6c0315d5836f1329a54544e698b2367e599e1cc0413acd77078e5d8464d", "retrieved_at": "2026-10-09T08:52:55.139314+00:00"}, {"id": "275941-1", "question_id": 275941, "category": "door_fault", "kind": "image", "url": "https://i.sstatic.net/lwrCN.jpg", "alt": "Outside view", "source_url": "https://diy.stackexchange.com/questions/275941/frozen-kwikset-door-latch", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 1512, "height": 2016, "final_url": "https://i.sstatic.net/lwrCN.jpg", "local_path": "media/020/07.jpg", "sha256": "e603aecee295cb1389fe3bad3afc4a3fb908280d9d6b6c19ba8fb11fcc56ab18", "retrieved_at": "2026-10-09T08:52:57.860165+00:00"}]}, "image_count": 2}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
