INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-313310', 'Front door latch freezing in "open position" in cold weather', '门锁与门闩异常', 'https://diy.stackexchange.com/questions/313310/front-door-latch-freezing-in-open-position-in-cold-weather', FALSE, '{"id": "diy-313310", "name": "Front door latch freezing in \"open position\" in cold weather", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "门锁与门闩异常", "source_url": "https://diy.stackexchange.com/questions/313310/front-door-latch-freezing-in-open-position-in-cold-weather", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "alex_danielssen", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "indoor-repair-20261009", "source_metadata": "indoor-repair-20261009\\dataset.json", "image_ids": ["b38028c2e750ace15be23c7b3915d9c13a4ac99265c3627f6a0c8c8188267d32", "ff352adc07d48ae5902922aef6e2ebbb02d906961304f1c41a790a7624994c4c"], "original_record": {"question_id": 313310, "category": "door_fault", "category_zh": "门锁与门闩异常", "title": "Front door latch freezing in \"open position\" in cold weather", "reported_symptom": "I live in Canada in a recently renovated house with tight building envelope.  I''ve noticed in cold weather, roughly -15C (5F) or below, the front door latch (will sometimes get stuck in the open position (i.e. the ''bolt'' will not come out of its hole, or will only partially return to the ''closed'' position), making it impossible to shut the door without manually pulling it out with a pair of pliers. I''ve opened up the handle and there is a fair amount of condensation on the latch mechanism.  I suspect that when I open the door, the cold end of the bolt freezes some of the water in the interior of the mechanism. The two screw holes in Figure 3 have big gaps in them so warm house air is free to go into the bore of the door. I also notice that the exterior ''thumb latch'' handle (Figure 4) seems more prone to not returning to its neutral position than the interior handle (Figure 3). I notice sometimes a bit (or a lot!) of frost accumulating in the there opening, which probably doesn''t help. Indoor humidity is 40-45% (Figure 2). I realize this is a bit higher than recommended, but its tricky to get it into the 30''s. We run the HRV ~40 minutes/hr (I''m not sure the humidistat function works on our thermostat/controller). Figure 1 Figure 2 Figure 3 Figure 4 My question How can I help prevent the latch from icing up in cold weather?  I''m especially looking for solutions at the door. I know reducing humidity will help but super low humidity will cause me other problems with wood, instruments, etc. However, if you think I''m being an idiot and just need to turn my house into a desert, that''s a valid answer too. I''ve considered: a waterproof lubricant for the door latch, but not sure what to use - I tried graphite lube but it just made a mess (as you can see in the pictures) sealing the holes in the door latch to reduce warm air flow into the door bore. replacing the exterior thumb-handle with a regular handle.", "source_url": "https://diy.stackexchange.com/questions/313310/front-door-latch-freezing-in-open-position-in-cold-weather", "author": "alex_danielssen", "author_url": "https://diy.stackexchange.com/users/103429/alex-danielssen", "content_license": "CC BY-SA 4.0", "created_at_unix": 1737309711, "raw_path": "raw/door_fault.json", "raw_sha256": "780531b2dc2faab6006c729b46d0bb48bef2d6f7ef15d3e2df908227a295e62c", "retrieved_at": "2026-10-09T08:49:29.394416+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "assets": [{"id": "313310-0", "question_id": 313310, "category": "door_fault", "kind": "image", "url": "https://i.sstatic.net/2vCzw9M6.jpg", "alt": "indoor latch", "source_url": "https://diy.stackexchange.com/questions/313310/front-door-latch-freezing-in-open-position-in-cold-weather", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 1536, "height": 2048, "final_url": "https://i.sstatic.net/2vCzw9M6.jpg", "local_path": "media/020/08.jpg", "sha256": "b38028c2e750ace15be23c7b3915d9c13a4ac99265c3627f6a0c8c8188267d32", "retrieved_at": "2026-10-09T08:52:59.203870+00:00"}, {"id": "313310-1", "question_id": 313310, "category": "door_fault", "kind": "image", "url": "https://i.sstatic.net/TMI6mTkJ.png", "alt": "january humidity", "source_url": "https://diy.stackexchange.com/questions/313310/front-door-latch-freezing-in-open-position-in-cold-weather", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 1647, "height": 450, "final_url": "https://i.sstatic.net/TMI6mTkJ.png", "local_path": "media/020/09.png", "sha256": "ff352adc07d48ae5902922aef6e2ebbb02d906961304f1c41a790a7624994c4c", "retrieved_at": "2026-10-09T08:53:01.199304+00:00"}]}, "image_count": 2}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
