INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-211998', 'Washing machine drain leak / back up', '家电漏水', 'https://diy.stackexchange.com/questions/211998/washing-machine-drain-leak-back-up', FALSE, '{"id": "diy-211998", "name": "Washing machine drain leak / back up", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "家电漏水", "source_url": "https://diy.stackexchange.com/questions/211998/washing-machine-drain-leak-back-up", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "a.m.2456", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "indoor-repair-20261009", "source_metadata": "indoor-repair-20261009\\dataset.json", "image_ids": ["9dd59c7a690333f934aa40f1d29d64397ba52fd02b8a845b683f7d45b5ef0382"], "original_record": {"question_id": 211998, "category": "appliance_leak", "category_zh": "家电漏水", "title": "Washing machine drain leak / back up", "reported_symptom": "Hi I recently bought a new Beko washing machine with dryer (model WD75141), just after 5-6 washes I saw water leakage on the floor, most probably drain water by the looks of it. I am no expert my question is does this water also back flow into the laundry and subsequently the laundry is still dirty? The drain pipe goes to a drain hose around 90cm high the same height as the washing machine and in the instructions it says maximum 90cm. I saw the water leakage mid cycle, and afterwards I saw the washing machine removing water and filling drum with new water and spinning because in this cycle I did not see detergent bubbles in water. My question if the washing machine does that does it mean laundry is dirty? I am not sure if there could be a backup of water. Since the machine is a washer-dryer, at the end clothes were less dry than usual because the clothes got wrapped into a bed sheet which perhaps prevented drying, I am not sure. This drying less happened to me once before with another washing machine because of the same bed sheet.", "source_url": "https://diy.stackexchange.com/questions/211998/washing-machine-drain-leak-back-up", "author": "a.m.2456", "author_url": "https://diy.stackexchange.com/users/127597/a-m-2456", "content_license": "CC BY-SA 4.0", "created_at_unix": 1608840819, "raw_path": "raw/appliance_leak.json", "raw_sha256": "0445888e600f45a4442b407e8edfcdddf1f92c0d8cfd985853ed681bdafd5ff9", "retrieved_at": "2026-10-09T08:49:31.452216+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "assets": [{"id": "211998-0", "question_id": 211998, "category": "appliance_leak", "kind": "image", "url": "https://i.sstatic.net/9n5qf.jpg", "alt": "enter image description here", "source_url": "https://diy.stackexchange.com/questions/211998/washing-machine-drain-leak-back-up", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 1600, "height": 2844, "final_url": "https://i.sstatic.net/9n5qf.jpg", "local_path": "media/020/10.jpg", "sha256": "9dd59c7a690333f934aa40f1d29d64397ba52fd02b8a845b683f7d45b5ef0382", "retrieved_at": "2026-10-09T08:53:05.001481+00:00"}]}, "image_count": 1}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
