INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-245518', 'Washing machine drainage leaking - new appliance', '家电漏水', 'https://diy.stackexchange.com/questions/245518/washing-machine-drainage-leaking-new-appliance', FALSE, '{"id": "diy-245518", "name": "Washing machine drainage leaking - new appliance", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "家电漏水", "source_url": "https://diy.stackexchange.com/questions/245518/washing-machine-drainage-leaking-new-appliance", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "Jude", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "indoor-repair-20261009", "source_metadata": "indoor-repair-20261009\\dataset.json", "image_ids": ["90bd79b874a6279712ea05d2eb591fdc2eba500d2a33875467ea947ce05eae5c"], "original_record": {"question_id": 245518, "category": "appliance_leak", "category_zh": "家电漏水", "title": "Washing machine drainage leaking - new appliance", "reported_symptom": "I have a new washing machine (there wasn''t one there before as I''ve recently moved in). When the machine is running the water spouts out particularly through a vertical ''vent'' hose leaving a small flood. I''ve cleaned the parts out and even tried to buy  new piping from Screwfix and B&Q (they didn''t fit together) as I thought I could just get away with no ''vertical vent'' as I''ve never had one before. i paid money for Hotpoint to fit the washing machine but the guy just said it was leaking and he hadn''t seen plumbing like that before. How can I resolve the problem myself without waiting on a plumber?", "source_url": "https://diy.stackexchange.com/questions/245518/washing-machine-drainage-leaking-new-appliance", "author": "Jude", "author_url": "https://diy.stackexchange.com/users/149153/jude", "content_license": "CC BY-SA 4.0", "created_at_unix": 1646143115, "raw_path": "raw/appliance_leak.json", "raw_sha256": "0445888e600f45a4442b407e8edfcdddf1f92c0d8cfd985853ed681bdafd5ff9", "retrieved_at": "2026-10-09T08:49:31.452562+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "assets": [{"id": "245518-0", "question_id": 245518, "category": "appliance_leak", "kind": "image", "url": "https://i.sstatic.net/ZfbgT.jpg", "alt": "under cabinet image showing drain line with AAV", "source_url": "https://diy.stackexchange.com/questions/245518/washing-machine-drainage-leaking-new-appliance", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 1721, "height": 2366, "final_url": "https://i.sstatic.net/ZfbgT.jpg", "local_path": "media/020/11.jpg", "sha256": "90bd79b874a6279712ea05d2eb591fdc2eba500d2a33875467ea947ce05eae5c", "retrieved_at": "2026-10-09T08:53:05.801315+00:00"}]}, "image_count": 1}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
