INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-94434', 'how to extend washing machine drainage hose such that it doesn''t leak', '家电漏水', 'https://diy.stackexchange.com/questions/94434/how-to-extend-washing-machine-drainage-hose-such-that-it-doesnt-leak', FALSE, '{"id": "diy-94434", "name": "how to extend washing machine drainage hose such that it doesn''t leak", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "家电漏水", "source_url": "https://diy.stackexchange.com/questions/94434/how-to-extend-washing-machine-drainage-hose-such-that-it-doesnt-leak", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "Chris Morris", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/", "notes": null, "source_batch": "indoor-repair-20261009", "source_metadata": "indoor-repair-20261009\\dataset.json", "image_ids": ["72366eca7385d9cc01aa4b19e1e4bf5a67fe80f79ca7a5b9bcba61c852980897", "b0c9959e9402865c9e862522dbf2bb4f6add1057775bfd4f9f8a9c984bc8e86d"], "original_record": {"question_id": 94434, "category": "appliance_leak", "category_zh": "家电漏水", "title": "how to extend washing machine drainage hose such that it doesn''t leak", "reported_symptom": "I have a portable washing machine that I want to keep in one of our bedrooms and thus need to extend the stock drainage hose. My current solution is: buy the necessary length of clear plastic tubing wrap the existing hose with electrical tape until it barely fits inside the plastic tubing use a hose clamp to cinch down the tubing so that there are no leaks Unfortunately, my solution does not prevent all leaks; a small bit of water still leaks out. What are your suggestions?", "source_url": "https://diy.stackexchange.com/questions/94434/how-to-extend-washing-machine-drainage-hose-such-that-it-doesnt-leak", "author": "Chris Morris", "author_url": "https://diy.stackexchange.com/users/24133/chris-morris", "content_license": "CC BY-SA 3.0", "created_at_unix": 1468708321, "raw_path": "raw/appliance_leak.json", "raw_sha256": "0445888e600f45a4442b407e8edfcdddf1f92c0d8cfd985853ed681bdafd5ff9", "retrieved_at": "2026-10-09T08:49:31.452980+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/3.0/", "assets": [{"id": "94434-0", "question_id": 94434, "category": "appliance_leak", "kind": "image", "url": "https://i.sstatic.net/OV9PI.jpg", "alt": "original drainage hose w/ measurement from ruler", "source_url": "https://diy.stackexchange.com/questions/94434/how-to-extend-washing-machine-drainage-hose-such-that-it-doesnt-leak", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 2448, "height": 3264, "final_url": "https://i.sstatic.net/OV9PI.jpg", "local_path": "media/020/12.jpg", "sha256": "72366eca7385d9cc01aa4b19e1e4bf5a67fe80f79ca7a5b9bcba61c852980897", "retrieved_at": "2026-10-09T08:53:08.191764+00:00"}, {"id": "94434-1", "question_id": 94434, "category": "appliance_leak", "kind": "image", "url": "https://i.sstatic.net/yU8Wt.jpg", "alt": "original tube with tape and hose clamp", "source_url": "https://diy.stackexchange.com/questions/94434/how-to-extend-washing-machine-drainage-hose-such-that-it-doesnt-leak", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 3264, "height": 2448, "final_url": "https://i.sstatic.net/yU8Wt.jpg", "local_path": "media/020/13.jpg", "sha256": "b0c9959e9402865c9e862522dbf2bb4f6add1057775bfd4f9f8a9c984bc8e86d", "retrieved_at": "2026-10-09T08:53:09.893987+00:00"}]}, "image_count": 2}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, cate