INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-283698', 'What is this leaking port on the back of my Samsung washing machine?', '家电漏水', 'https://diy.stackexchange.com/questions/283698/what-is-this-leaking-port-on-the-back-of-my-samsung-washing-machine', FALSE, '{"id": "diy-283698", "name": "What is this leaking port on the back of my Samsung washing machine?", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "家电漏水", "source_url": "https://diy.stackexchange.com/questions/283698/what-is-this-leaking-port-on-the-back-of-my-samsung-washing-machine", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "Brett Sonflieth", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "indoor-repair-20261009", "source_metadata": "indoor-repair-20261009\\dataset.json", "image_ids": ["e1c04dfaf81d60fe556703fdaf981b8f209c0fb07001d9257f22b253fb3dbe0c"], "original_record": {"question_id": 283698, "category": "appliance_leak", "category_zh": "家电漏水", "title": "What is this leaking port on the back of my Samsung washing machine?", "reported_symptom": "I noticed that my Samsung washing machine is leaking at the end of the cycle from this port. Any idea what this port is?", "source_url": "https://diy.stackexchange.com/questions/283698/what-is-this-leaking-port-on-the-back-of-my-samsung-washing-machine", "author": "Brett Sonflieth", "author_url": "https://diy.stackexchange.com/users/175131/brett-sonflieth", "content_license": "CC BY-SA 4.0", "created_at_unix": 1696808978, "raw_path": "raw/appliance_leak.json", "raw_sha256": "0445888e600f45a4442b407e8edfcdddf1f92c0d8cfd985853ed681bdafd5ff9", "retrieved_at": "2026-10-09T08:49:31.453111+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "assets": [{"id": "283698-0", "question_id": 283698, "category": "appliance_leak", "kind": "image", "url": "https://i.sstatic.net/vBWjYl.jpg", "alt": "connections on rear of washing machine", "source_url": "https://diy.stackexchange.com/questions/283698/what-is-this-leaking-port-on-the-back-of-my-samsung-washing-machine", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 640, "height": 1137, "final_url": "https://i.sstatic.net/vBWjYl.jpg", "local_path": "media/020/14.jpg", "sha256": "e1c04dfaf81d60fe556703fdaf981b8f209c0fb07001d9257f22b253fb3dbe0c", "retrieved_at": "2026-10-09T08:53:12.049540+00:00"}]}, "image_count": 1}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
