INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-273378', 'Leaking washing machine valve stuck', '家电漏水', 'https://diy.stackexchange.com/questions/273378/leaking-washing-machine-valve-stuck', FALSE, '{"id": "diy-273378", "name": "Leaking washing machine valve stuck", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "家电漏水", "source_url": "https://diy.stackexchange.com/questions/273378/leaking-washing-machine-valve-stuck", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "Roger D", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "indoor-repair-20261009", "source_metadata": "indoor-repair-20261009\\dataset.json", "image_ids": ["5f78c7830c5ef9bdcf39e9aec316f2dc0a6b8e7da2c8507abb3368ec02289f1e"], "original_record": {"question_id": 273378, "category": "appliance_leak", "category_zh": "家电漏水", "title": "Leaking washing machine valve stuck", "reported_symptom": "I noticed both hot and cold water inlets to my washing machine were leaking in small amounts. Turning the valves off stopped the dripping. Of course, I wanted to replace the valves. I would possibly replace the cold water side myself, and have the more-coroded hot water side done by a pro. I''m having a terrible time trying to get the cold water valve off, and I''m afraid of damaging the copper pipe. Also, as snug as I secured the wrench on the valve-end, I''ve chewed some of it up. I''m trying to turn what I think is the end of the valve (the red arrow). There is NO nut (hex shape) anywhere on the other side of the threads (to the right of the red arrow) to hold on to with another wrench. I''ve sprayed rust penetrant on the valve end and threads several times, allowing some time on each application, but no luck. (I know it''s counter-clockwise.) So the questions are: Am I turning in the right spot? If 1 is yes, any ideas how to loosen the valve without damaging the pipe? (I''m really hoping to avoid using a torch, as there''s a wall very close.) Although I''m pretty sure I make no contact with the ''thing'' in the blue box. It''s now dripping when the water is turned back on. What is it? The T-handle at the top won''t budge by hand. The plastic tube coming off of it runs to the washer drain. Looks as though the other end of the T-handle might go into the pipe, though that''s a guess as I did not loosen the clamp around the pipe. (I thought that maybe this was a pressure relief mechanism, but why have it on the cold side and not on the hot side?) Thanks for any help.", "source_url": "https://diy.stackexchange.com/questions/273378/leaking-washing-machine-valve-stuck", "author": "Roger D", "author_url": "https://diy.stackexchange.com/users/156554/roger-d", "content_license": "CC BY-SA 4.0", "created_at_unix": 1685568509, "raw_path": "raw/appliance_leak.json", "raw_sha256": "0445888e600f45a4442b407e8edfcdddf1f92c0d8cfd985853ed681bdafd5ff9", "retrieved_at": "2026-10-09T08:49:31.453358+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "assets": [{"id": "273378-0", "question_id": 273378, "category": "appliance_leak", "kind": "image", "url": "https://i.sstatic.net/QM77m.jpg", "alt": "enter image description here", "source_url": "https://diy.stackexchange.com/questions/273378/leaking-washing-machine-valve-stuck", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 809, "height": 762, "final_url": "https://i.sstatic.net/QM77m.jpg", "local_path": "media/020/15.jpg", "sha256": "5f78c7830c5ef9bdcf39e9aec316f2dc0a6b8e7da2c8507abb3368ec02289f1e", "retrieved_at": "2026-10-09T08:53:13.528924+00:00"}]}, "image_count": 1}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
