INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-256133', 'Ceiling fan light flickers when fan is used', '灯具异常', 'https://diy.stackexchange.com/questions/256133/ceiling-fan-light-flickers-when-fan-is-used', FALSE, '{"id": "diy-256133", "name": "Ceiling fan light flickers when fan is used", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "灯具异常", "source_url": "https://diy.stackexchange.com/questions/256133/ceiling-fan-light-flickers-when-fan-is-used", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "MonkeyZeus", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "used-fixtures-20261009", "source_metadata": "used-fixtures-20261009\\dataset.json", "image_ids": ["a6487ad491f084b59f9e85462eb52c6c3137cbb4e8f2d0029f1a084db492d25f"], "original_record": {"question_id": 256133, "category": "light_fault", "category_zh": "灯具异常", "title": "Ceiling fan light flickers when fan is used", "reported_symptom": "I have a double-gang box with a Leviton dimmer switch , a Lutron fan switch , and ran 14/3 to a Hunter 53408 ceiling fan . I wired everything up and the controls work well, independently; the Leviton dims the T12 3.5W LED bulbs and the Lutron adjusts the fan from low to medium to high. When both are turned on and I adjust the Lutron speed, the bulbs will sporadically flicker off and on. This does not happen every single time but there''s a 50% chance that a flicker occurs when adjusting the fan speed. Do I have a hardware incompatibility? One guess is that the Lutron is causing some weird fluctuation on the neutral but I''m no expert. My second guess is that the leads for the fan versus light is not adequately separated inside the fan housing. Per request, below is a wiring diagram. I made it from memory so if something looks off then please request clarity. Update 1: Adjusting the ceiling fan speed will sometimes make the ceiling light stay on at full brightness after flickering. Turning the Lutron on or off also affects the behavior of the light. The flicker will also affect a dimmer+light on the same circuit in an adjacent hallway. Same Leviton dimmer but this has a Great Value bulb. This light always returns to normal after a flicker. Update 2: Leaving the Lutron on high and using the pull strings on the fan causes zero issues for the bulbs. There is another light on the same circuit which is not dimmable and it experiences zero flicker.", "source_url": "https://diy.stackexchange.com/questions/256133/ceiling-fan-light-flickers-when-fan-is-used", "author": "MonkeyZeus", "author_url": "https://diy.stackexchange.com/users/42053/monkeyzeus", "content_license": "CC BY-SA 4.0", "created_at_unix": 1662469936, "raw_path": "raw/light_fault.json", "raw_sha256": "79323acd0d906c3f669c508666031010496c23099106e078e553458a47fc00e4", "retrieved_at": "2026-10-09T08:57:57.897717+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "assets": [{"id": "256133-0", "question_id": 256133, "category": "light_fault", "kind": "image", "url": "https://i.sstatic.net/UmVYr.png", "alt": "enter image description here", "source_url": "https://diy.stackexchange.com/questions/256133/ceiling-fan-light-flickers-when-fan-is-used", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 1270, "height": 660, "final_url": "https://i.sstatic.net/UmVYr.png", "local_path": "media/000/00.png", "sha256": "a6487ad491f084b59f9e85462eb52c6c3137cbb4e8f2d0029f1a084db492d25f", "retrieved_at": "2026-10-09T08:58:42.016870+00:00"}]}, "image_count": 1}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
