INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-146039', 'Help with lights flickering at weird regular interval', '灯具异常', 'https://diy.stackexchange.com/questions/146039/help-with-lights-flickering-at-weird-regular-interval', FALSE, '{"id": "diy-146039", "name": "Help with lights flickering at weird regular interval", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "灯具异常", "source_url": "https://diy.stackexchange.com/questions/146039/help-with-lights-flickering-at-weird-regular-interval", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "nbdyowens", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "used-fixtures-20261009", "source_metadata": "used-fixtures-20261009\\dataset.json", "image_ids": ["04eeb1b041c4e8574a987fd7d3a7bca931e4b57f02a558a11b321dbcd5bd62b7", "785c233f88c4001e99561c63108a741defbb8c53432efe3f0ce4e5e36799b076"], "original_record": {"question_id": 146039, "category": "light_fault", "category_zh": "灯具异常", "title": "Help with lights flickering at weird regular interval", "reported_symptom": "Lights flicker for ~17 seconds at 1 flash/sec, then normal for ~23 seconds. This cycle repeats itself continuously. The video starts with the 23 second \"normal\" period, followed by 17 seconds of flickering, and shows 2 cycles. May need to turn screen brightness up, but if you watch closely the flashes are evident. Context about my home''s electrical system: video is of ceiling light flickering is not isolated to a single circuit. Occurs in bedroom\ncircuit, bathroom circuit, kitchen circuit (fridge light),\noutside garage light, and floor lamps plugged into outlets 1950''s house, copper wiring, no ground on most circuits except for\nkitchen. Location is in Indiana, USA In Jan 2018, recently after purchasing house, I: installed GFCI outlets at the head of each circuit to conform with NEC code for having 3-prong (grounded) outlets on wiring with no ground. replaced all other normal receptacles and switches replaced all lights with LEDs flickering phenomenon only started about 4 months ago, well after I made above changes I have a single dimmer switch for kitchen ceiling light, which is LED. Both dimmer switch and LED claim compatibility with dimming functionality. Oddly enough, this light doesn''t flicker, at least not strongly enough that I can perceive it 100 amp service Things I''ve tried already: Had utility company replace connections to weather-head due to\nimbalance on legs of main coming into panel. Flickering was occurring\nbefore this, and this did not solve. Asked utility company if transformer was sized appropriately/working correctly. Technician said yes, but also didn''t climb pole to inspect transformer. Inspected breakers on all circuits. Replaced some that I thought\ncould have poor connection, but flickering continued. Inspected panel for any loose connections at bus bar, tightened a few, but found nothing suspect I''m fairly handy, an engineer, and confident in my ability to troubleshoot without getting myself electrocuted, but I''m out of ideas. Any thoughts? Link to video Panel model info:", "source_url": "https://diy.stackexchange.com/questions/146039/help-with-lights-flickering-at-weird-regular-interval", "author": "nbdyowens", "author_url": "https://diy.stackexchange.com/users/90479/nbdyowens", "content_license": "CC BY-SA 4.0", "created_at_unix": 1535563158, "raw_path": "raw/light_fault.json", "raw_sha256": "79323acd0d906c3f669c508666031010496c23099106e078e553458a47fc00e4", "retrieved_at": "2026-10-09T08:57:57.898679+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "assets": [{"id": "146039-0", "question_id": 146039, "category": "light_fault", "kind": "image", "url": "https://i.sstatic.net/r02Sy.jpg", "alt": "Panel Model Pic 1", "source_url": "https://diy.stackexchange.com/questions/146039/help-with-lights-flickering-at-weird-regular-interval", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 2016, "height": 1512, "final_url": "https://i.sstatic.net/r02Sy.jpg", "local_path": "media/000/01.jpg", "sha256": "04eeb1b041c4e8574a987fd7d3a7bca931e4b57f02a558a11b321dbcd5bd62b7", "retrieved_at": "2026-10-09T08:58:44.088374+00:00"}, {"id": "146039-1", "question_id": 146039, "category": "light_fault", "kind": "image", "url": "https://i.sstatic.net/i7M8S.jpg", "alt": "Panel Model Pic 2", "source_url": "https://diy.stackexchange.com/questions/146039/help-with-lights-flickering-at-weird-regular-interval", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 4032, "height": 3024, "final_url": "https://i.sstatic.net/i7M8S.jpg", "local_path": "media/000/02.jpg", "sha256": "785c233f88c4001e99561c63108a741defbb8c53432efe3f0ce4e5e36799b076", "retrieved_at": "2026-10-09T08:58:45.986579+00:00"}]}, "image_count": 2}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
