INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-276839', 'Why might my ceiling light be flickering?', '灯具异常', 'https://diy.stackexchange.com/questions/276839/why-might-my-ceiling-light-be-flickering', FALSE, '{"id": "diy-276839", "name": "Why might my ceiling light be flickering?", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "灯具异常", "source_url": "https://diy.stackexchange.com/questions/276839/why-might-my-ceiling-light-be-flickering", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "Darren", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "used-fixtures-20261009", "source_metadata": "used-fixtures-20261009\\dataset.json", "image_ids": ["65e829f254c0ad327aa838d8fd7a8b92282dfc43c9d9bf1b8ea64abb1e0dd2ee", "43c556dab9cabafbb545b69fa1c5b7398b3f504766b5a06f0cfa90b0ef2d7d1f"], "original_record": {"question_id": 276839, "category": "light_fault", "category_zh": "灯具异常", "title": "Why might my ceiling light be flickering?", "reported_symptom": "I have two lights in my bedroom on the same circuit with a single switch. One of them (always the same one) will sometimes flicker to the point that it''s strobing. It doesn''t do it all of the time, and there doesn''t seem to be a correlation between it doing it and how long it''s been switched on (sometimes it does it straight away, sometimes it can be on for ages and not do it). I am assuming there''s no issue with the supply or fuses or I''d be seeing it on both light fittings. I''ve tried a different bulb. The bedroom is in an extension that is about 5 years old so the wiring should be fairly up to code and in good condition. I can''t access the wiring above it as the attic is boarded and insulated, but nothing should be disturbing it if, for example, there was a loose connection. There is nothing obviously (to me) wrong with the wiring. Switch wiring: Good light wiring: Problem light wiring:", "source_url": "https://diy.stackexchange.com/questions/276839/why-might-my-ceiling-light-be-flickering", "author": "Darren", "author_url": "https://diy.stackexchange.com/users/133188/darren", "content_license": "CC BY-SA 4.0", "created_at_unix": 1689598708, "raw_path": "raw/light_fault.json", "raw_sha256": "79323acd0d906c3f669c508666031010496c23099106e078e553458a47fc00e4", "retrieved_at": "2026-10-09T08:57:57.899192+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "assets": [{"id": "276839-0", "question_id": 276839, "category": "light_fault", "kind": "image", "url": "https://i.sstatic.net/GG9aV.jpg", "alt": "enter image description here", "source_url": "https://diy.stackexchange.com/questions/276839/why-might-my-ceiling-light-be-flickering", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 768, "height": 1024, "final_url": "https://i.sstatic.net/GG9aV.jpg", "local_path": "media/000/03.jpg", "sha256": "65e829f254c0ad327aa838d8fd7a8b92282dfc43c9d9bf1b8ea64abb1e0dd2ee", "retrieved_at": "2026-10-09T08:58:47.647428+00:00"}, {"id": "276839-1", "question_id": 276839, "category": "light_fault", "kind": "image", "url": "https://i.sstatic.net/2rIDO.jpg", "alt": "enter image description here", "source_url": "https://diy.stackexchange.com/questions/276839/why-might-my-ceiling-light-be-flickering", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 1024, "height": 768, "final_url": "https://i.sstatic.net/2rIDO.jpg", "local_path": "media/000/04.jpg", "sha256": "43c556dab9cabafbb545b69fa1c5b7398b3f504766b5a06f0cfa90b0ef2d7d1f", "retrieved_at": "2026-10-09T08:58:49.698860+00:00"}]}, "image_count": 2}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
