INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-291722', 'Light working after washing machine has run', '洗衣机异常', 'https://diy.stackexchange.com/questions/291722/light-working-after-washing-machine-has-run', FALSE, '{"id": "diy-291722", "name": "Light working after washing machine has run", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "洗衣机异常", "source_url": "https://diy.stackexchange.com/questions/291722/light-working-after-washing-machine-has-run", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "JenserCube", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "used-fixtures-20261009", "source_metadata": "used-fixtures-20261009\\dataset.json", "image_ids": ["a4a7420707859f71710f4a11fbc4be3daec134e76c25cae37965265b7c1ada10"], "original_record": {"question_id": 291722, "category": "washer_fault", "category_zh": "洗衣机异常", "title": "Light working after washing machine has run", "reported_symptom": "An electrician has looked at this and said it is legal because it was up to code when it was made. But if changes are done to it, it must be up to the current code. I will have it fixed by the same electrician, but I want to understand how the following can happen.\nHe also told me a bit about the wiring which I have illustrated here. The switch at C turns on the lamp in the ceiling E. The switch at D can turn on an additional lamp, but nothing is currently hooked up to that outlet. The switches at A and B each turn on the outlet under them. Everything was working as it should. I hooked up a few things at A and B (such as a vacuum cleaner). Everything was still working fine. I hooked up a charger for a laptop at B. The light at E flashed on and off for a few seconds and then turned off. I thought it was the bulb, but that was not the case (I have checked that several times - the issue is never the bulb).\nThe situation - neither A, B or E is working. I checked and could see some current was flowing when I switched them on, but I don''t have the tools to see how much. I left the switch at C turned on even though it had no effect. Suddenly, the lamp at E worked again. C could be turned on and off and it worked as expected. I was puzzled. Stupid as I was, I plugged something into A again. E stopped working again. I left C turned on again hoping it would start working again. Suddenly, the light turned on. I noticed it turned on while the washing machine was running at its loudest. Once the washing machine stopped, E turned off again. This pattern repeated two more times. The fourth time, C worked again without the need for the washing machine being on. Even more puzzled I decided not to touch A or B since I now had working light at E. However, I had to turn off F to do work on something else. Once again E has stopped working, still has some current running through it. It no longer seems to be effected by the washing machine. I have checked all the places I can and there is no loose connections. I cannot figure out how all this is effecting each other, and I am quite puzzled by it. How can this be?\nI can add further explanations and pictures if that is needed.", "source_url": "https://diy.stackexchange.com/questions/291722/light-working-after-washing-machine-has-run", "author": "JenserCube", "author_url": "https://diy.stackexchange.com/users/165640/jensercube", "content_license": "CC BY-SA 4.0", "created_at_unix": 1705874483, "raw_path": "raw/washer_fault.json", "raw_sha256": "1761ce17c61d7d79edfc60346d05348e7f56b1e2ebb1619d0c8495fcb201f57f", "retrieved_at": "2026-10-09T08:57:59.011818+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "assets": [{"id": "291722-0", "question_id": 291722, "category": "washer_fault", "kind": "image", "url": "https://i.sstatic.net/JxQI9.png", "alt": "Wires and switches", "source_url": "https://diy.stackexchange.com/questions/291722/light-working-after-washing-machine-has-run", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 641, "height": 389, "final_url": "https://i.sstatic.net/JxQI9.png", "local_path": "media/000/05.png", "sha256": "a4a7420707859f71710f4a11fbc4be3daec134e76c25cae37965265b7c1ada10", "retrieved_at": "2026-10-09T08:58:51.580267+00:00"}]}, "image_count": 1}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
