INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-103738', 'my washing machine was automatically stop and this message was shown', '洗衣机异常', 'https://diy.stackexchange.com/questions/103738/my-washing-machine-was-automatically-stop-and-this-message-was-shown', FALSE, '{"id": "diy-103738", "name": "my washing machine was automatically stop and this message was shown", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "洗衣机异常", "source_url": "https://diy.stackexchange.com/questions/103738/my-washing-machine-was-automatically-stop-and-this-message-was-shown", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "Rohit Mahadik", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/", "notes": null, "source_batch": "used-fixtures-20261009", "source_metadata": "used-fixtures-20261009\\dataset.json", "image_ids": ["d2132607e8e1de3dd4f8000b47791cf2abfd416d4b523137121d7a4fac3a62b3"], "original_record": {"question_id": 103738, "category": "washer_fault", "category_zh": "洗衣机异常", "title": "my washing machine was automatically stop and this message was shown", "reported_symptom": "Samsung washing machine was automatically stopped and not working any botton exept power botton what should i do give any suggestions", "source_url": "https://diy.stackexchange.com/questions/103738/my-washing-machine-was-automatically-stop-and-this-message-was-shown", "author": "Rohit Mahadik", "author_url": "https://diy.stackexchange.com/users/63363/rohit-mahadik", "content_license": "CC BY-SA 3.0", "created_at_unix": 1480734522, "raw_path": "raw/washer_fault.json", "raw_sha256": "1761ce17c61d7d79edfc60346d05348e7f56b1e2ebb1619d0c8495fcb201f57f", "retrieved_at": "2026-10-09T08:57:59.012294+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis