INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-200955', 'Washing Machine door locking/lights working, but no power to solenoid or motor', '洗衣机异常', 'https://diy.stackexchange.com/questions/200955/washing-machine-door-locking-lights-working-but-no-power-to-solenoid-or-motor', FALSE, '{"id": "diy-200955", "name": "Washing Machine door locking/lights working, but no power to solenoid or motor", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "洗衣机异常", "source_url": "https://diy.stackexchange.com/questions/200955/washing-machine-door-locking-lights-working-but-no-power-to-solenoid-or-motor", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "Ashley Reid", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "used-fixtures-20261009", "source_metadata": "used-fixtures-20261009\\dataset.json", "image_ids": ["8e9b3677be17b5ec14f939454472509791b6eed3ab54b8ac785dbae6836051cc"], "original_record": {"question_id": 200955, "category": "washer_fault", "category_zh": "洗衣机异常", "title": "Washing Machine door locking/lights working, but no power to solenoid or motor", "reported_symptom": "My machine is turning on with the led''s lighting, allowing me to select and start a program, doors locking and then the counter starts to countdown as normal. But nothing else happens, no water and no motor. I have tried spin modes etc, but they are all the same. I have checked that the solenoids work when powered from an external source, But they are not receiving power from the control unit.\nThere is still meat on the motor bushes and the drum spins freely. This is my first time looking at fixing a washing machine so I don''t really know what else I can check, If there are fusees or other safety ''trips'' etc? That said, I would have thought that if that was the issue there would be an Error message showing? is there maybe a relay I can replace? or..? Any help would be greatly appreciated! Ash Machine: Electrolux / Zanussi ZWF12280W EDIT: inspired by jwh20''s comment bellow, I took a closer look at the control board. I think it might be something to do with the ''chard'' section.", "source_url": "https://diy.stackexchange.com/questions/200955/washing-machine-door-locking-lights-working-but-no-power-to-solenoid-or-motor", "author": "Ashley Reid", "author_url": "https://diy.stackexchange.com/users/122086/ashley-reid", "content_license": "CC BY-SA 4.0", "created_at_unix": 1597331650, "raw_path": "raw/washer_fault.json", "raw_sha256": "1761ce17c61d7d79edfc60346d05348e7f56b1e2ebb1619d0c8495fcb201f57f", "retrieved_at": "2026-10-09T08:57:59.013141+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "assets": [{"id": "200955-0", "question_id": 200955, "category": "washer_fault", "kind": "image", "url": "https://i.sstatic.net/VWtgJ.jpg", "alt": "enter image description here", "source_url": "https://diy.stackexchange.com/questions/200955/washing-machine-door-locking-lights-working-but-no-power-to-solenoid-or-motor", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 2991, "height": 2236, "final_url": "https://i.sstatic.net/VWtgJ.jpg", "local_path": "media/000/08.jpg", "sha256": "8e9b3677be17b5ec14f939454472509791b6eed3ab54b8ac785dbae6836051cc", "retrieved_at": "2026-10-09T08:58:58.305444+00:00"}]}, "image_count": 1}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
