INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-28940', 'What can I do if my washing machine inlet hoses are not compatible with the plumbing?', '洗衣机异常', 'https://diy.stackexchange.com/questions/28940/what-can-i-do-if-my-washing-machine-inlet-hoses-are-not-compatible-with-the-plum', FALSE, '{"id": "diy-28940", "name": "What can I do if my washing machine inlet hoses are not compatible with the plumbing?", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "洗衣机异常", "source_url": "https://diy.stackexchange.com/questions/28940/what-can-i-do-if-my-washing-machine-inlet-hoses-are-not-compatible-with-the-plum", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "Vira", "license": "CC BY-SA 3.0", "license_url": "https://creativecommons.org/licenses/by-sa/3.0/", "notes": null, "source_batch": "used-fixtures-20261009", "source_metadata": "used-fixtures-20261009\\dataset.json", "image_ids": ["59485749d6278cb449574dc0b849b5ec643d1ce236ea68740ba1a720a6b90735"], "original_record": {"question_id": 28940, "category": "washer_fault", "category_zh": "洗衣机异常", "title": "What can I do if my washing machine inlet hoses are not compatible with the plumbing?", "reported_symptom": "I purchased a fully automatic washing machine and little did I realize that it requires special plumbing to fit inlet hoses to water source. All I have got in my house are the taps to which it can be connected.I thought that I would be able to connect hose to tap when I operate washing machine and then remove it. But looks like this plan will not work. I want to know if I can use inlet hose of semi-automatic washing machine (which doesn''t require permanent fitting) with automatic washing machine? The hose connector looks like:", "source_url": "https://diy.stackexchange.com/questions/28940/what-can-i-do-if-my-washing-machine-inlet-hoses-are-not-compatible-with-the-plum", "author": "Vira", "author_url": "https://diy.stackexchange.com/users/13597/vira", "content_license": "CC BY-SA 3.0", "created_at_unix": 1371888956, "raw_path": "raw/washer_fault.json", "raw_sha256": "1761ce17c61d7d79edfc60346d05348e7f56b1e2ebb1619d0c8495fcb201f57f", "retrieved_at": "2026-10-09T08:57:59.013726+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/3.0/", "assets": [{"id": "28940-0", "question_id": 28940, "category": "washer_fault", "kind": "image", "url": "https://i.sstatic.net/hjzt7.jpg", "alt": "sample image", "source_url": "https://diy.stackexchange.com/questions/28940/what-can-i-do-if-my-washing-machine-inlet-hoses-are-not-compatible-with-the-plum", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 394, "height": 394, "final_url": "https://i.sstatic.net/hjzt7.jpg", "local_path": "media/000/09.jpg", "sha256": "59485749d6278cb449574dc0b849b5ec643d1ce236ea68740ba1a720a6b90735", "retrieved_at": "2026-10-09T08:58:59.566193+00:00"}]}, "image_count": 1}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
