INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-271554', 'Samsung washing machine on the fritz', '洗衣机异常', 'https://diy.stackexchange.com/questions/271554/samsung-washing-machine-on-the-fritz', FALSE, '{"id": "diy-271554", "name": "Samsung washing machine on the fritz", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "洗衣机异常", "source_url": "https://diy.stackexchange.com/questions/271554/samsung-washing-machine-on-the-fritz", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "5000fingers", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "used-fixtures-20261009", "source_metadata": "used-fixtures-20261009\\dataset.json", "image_ids": ["b84c578a15afcfafe345b0f77d0c91754f169d3baf6544c8ce948acfb5dee31f"], "original_record": {"question_id": 271554, "category": "washer_fault", "category_zh": "洗衣机异常", "title": "Samsung washing machine on the fritz", "reported_symptom": "I have a Samsung washing machine (WF42H5, if that means anything to you), about 5 years old, that suddenly stopped working. All of its lights flash on and off (see photo), and it is unresponsive to any buttons. Nothing strange happened to the washing machine or our electric service, it just stopped working for no apparent reason. I have unplugged it, and plugged it back in, and no change. What little I have been able to find on the internet about this condition with Samsung washing machines is not encouraging. But I''m hoping that there might be some experts on this board who can point me to a possible fix.", "source_url": "https://diy.stackexchange.com/questions/271554/samsung-washing-machine-on-the-fritz", "author": "5000fingers", "author_url": "https://diy.stackexchange.com/users/144902/5000fingers", "content_license": "CC BY-SA 4.0", "created_at_unix": 1682717809, "raw_path": "raw/washer_fault.json", "raw_sha256": "1761ce17c61d7d79edfc60346d05348e7f56b1e2ebb1619d0c8495fcb201f57f", "retrieved_at": "2026-10-09T08:57:59.013900+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "assets": [{"id": "271554-0", "question_id": 271554, "category": "washer_fault", "kind": "image", "url": "https://i.sstatic.net/8owU2.jpg", "alt": "Flights Flashing", "source_url": "https://diy.stackexchange.com/questions/271554/samsung-washing-machine-on-the-fritz", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 2080, "height": 1360, "final_url": "https://i.sstatic.net/8owU2.jpg", "local_path": "media/000/10.jpg", "sha256": "b84c578a15afcfafe345b0f77d0c91754f169d3baf6544c8ce948acfb5dee31f", "retrieved_at": "2026-10-09T08:59:02.358151+00:00"}]}, "image_count": 1}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
