INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-150581', 'Why is my new toilet running so much?', '马桶异常', 'https://diy.stackexchange.com/questions/150581/why-is-my-new-toilet-running-so-much', FALSE, '{"id": "diy-150581", "name": "Why is my new toilet running so much?", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "马桶异常", "source_url": "https://diy.stackexchange.com/questions/150581/why-is-my-new-toilet-running-so-much", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "Altoban", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "used-toilets-20261009", "source_metadata": "used-toilets-20261009\\dataset.json", "image_ids": ["b48db7a19cc5825fa5cc26bc7c15ab4c25aa6bed2d249da6436244d8017b806d"], "original_record": {"question_id": 150581, "category": "toilet_fault", "category_zh": "马桶异常", "title": "Why is my new toilet running so much?", "reported_symptom": "Toilet is only several months old and now it''s running like crazy. The water leaks into the bowel all day. Been weeks now, and for some reason it leaves dirt streaks on the bowel from tank. The trickle is so loud, something has to be done. update: week later, my other bathroom toilet stopped working (no water goes into tank), im thinking all this is because of the sediment that came with the water.", "source_url": "https://diy.stackexchange.com/questions/150581/why-is-my-new-toilet-running-so-much", "author": "Altoban", "author_url": "https://diy.stackexchange.com/users/58714/altoban", "content_license": "CC BY-SA 4.0", "created_at_unix": 1542201857, "raw_path": "raw/toilet_fault.json", "raw_sha256": "0db3f5e257d473cdfefa7383c493267a51f2796b234beecb2e9339fb7586f606", "retrieved_at": "2026-10-09T08:58:28.866468+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "assets": [{"id": "150581-0", "question_id": 150581, "category": "toilet_fault", "kind": "image", "url": "https://i.sstatic.net/aW05D.jpg", "alt": "here is Pic of inside tank", "source_url": "https://diy.stackexchange.com/questions/150581/why-is-my-new-toilet-running-so-much", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 451, "height": 800, "final_url": "https://i.sstatic.net/aW05D.jpg", "local_path": "media/000/00.jpg", "sha256": "b48db7a19cc5825fa5cc26bc7c15ab4c25aa6bed2d249da6436244d8017b806d", "retrieved_at": "2026-10-09T08:59:20.426193+00:00"}]}, "image_count": 1}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
