INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-147127', 'Troubleshooting a running toilet', '马桶异常', 'https://diy.stackexchange.com/questions/147127/troubleshooting-a-running-toilet', FALSE, '{"id": "diy-147127", "name": "Troubleshooting a running toilet", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "马桶异常", "source_url": "https://diy.stackexchange.com/questions/147127/troubleshooting-a-running-toilet", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "Bob Tway", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "used-toilets-20261009", "source_metadata": "used-toilets-20261009\\dataset.json", "image_ids": ["1285c77f10ad34f86e9f7d576185e64d17a20d0d5ee70af40854459ba50bbd71"], "original_record": {"question_id": 147127, "category": "toilet_fault", "category_zh": "马桶异常", "title": "Troubleshooting a running toilet", "reported_symptom": "My toilet has a slow but continual trickle of water running from the rim into the bowl. I presumed this was a misaligned float but when I pulled it up to its maximum height, the flow didn''t even stop. Looking it up it seems that the \"flapper\" is the most common cause of this problem. However I''m not a plumber and I can''t map any of the diagrams of photos I''ve seen with my actually toilet fixture. Here it is How do I make sense of this plumbing and find out what''s causing the leak into the toilet?", "source_url": "https://diy.stackexchange.com/questions/147127/troubleshooting-a-running-toilet", "author": "Bob Tway", "author_url": "https://diy.stackexchange.com/users/27558/bob-tway", "content_license": "CC BY-SA 4.0", "created_at_unix": 1537189215, "raw_path": "raw/toilet_fault.json", "raw_sha256": "0db3f5e257d473cdfefa7383c493267a51f2796b234beecb2e9339fb7586f606", "retrieved_at": "2026-10-09T08:58:28.867618+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "assets": [{"id": "147127-0", "question_id": 147127, "category": "toilet_fault", "kind": "image", "url": "https://i.sstatic.net/cN6Uu.jpg", "alt": "enter image description here", "source_url": "https://diy.stackexchange.com/questions/147127/troubleshooting-a-running-toilet", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 2047, "height": 1332, "final_url": "https://i.sstatic.net/cN6Uu.jpg", "local_path": "media/000/01.jpg", "sha256": "1285c77f10ad34f86e9f7d576185e64d17a20d0d5ee70af40854459ba50bbd71", "retrieved_at": "2026-10-09T08:59:23.079527+00:00"}]}, "image_count": 1}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
