INSERT INTO collected_data.repair_cases (id, name, category, source_url, actual_work_order, metadata) VALUES ('repair:diy-298906', 'Is this considered a running toilet? Recommend fix?', '马桶异常', 'https://diy.stackexchange.com/questions/298906/is-this-considered-a-running-toilet-recommend-fix', FALSE, '{"id": "diy-298906", "name": "Is this considered a running toilet? Recommend fix?", "record_type": "repair_post", "city": null, "region": null, "address": null, "property_id": null, "category": "马桶异常", "source_url": "https://diy.stackexchange.com/questions/298906/is-this-considered-a-running-toilet-recommend-fix", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": null, "author": "Paul", "license": "CC BY-SA 4.0", "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "notes": null, "source_batch": "used-toilets-20261009", "source_metadata": "used-toilets-20261009\\dataset.json", "image_ids": ["df9f62e943dd0c704eef2a2fd9d6580077ffdd60c5be33967afc22406dbbb35e", "95e8a89cceab23312a86018cb523b1281499fefcbc1cb1b326539f7ab1d48d34"], "original_record": {"question_id": 298906, "category": "toilet_fault", "category_zh": "马桶异常", "title": "Is this considered a running toilet? Recommend fix?", "reported_symptom": "From looking online, this seems much less pronounced with what people usually consider a running toilet, but I still suspect it is? If this is a running toilet , what’s the fix? Recommended part to replace? That tubing is fairly rigid compared to what I’ve seen googling. Additional pics of assembly: https://imgur.com/a/nszEHlz https://imgur.com/a/fY2mHQC Video of potential leaking: https://imgur.com/a/GJ1zcq9", "source_url": "https://diy.stackexchange.com/questions/298906/is-this-considered-a-running-toilet-recommend-fix", "author": "Paul", "author_url": "https://diy.stackexchange.com/users/187627/paul", "content_license": "CC BY-SA 4.0", "created_at_unix": 1714337533, "raw_path": "raw/toilet_fault.json", "raw_sha256": "0db3f5e257d473cdfefa7383c493267a51f2796b234beecb2e9339fb7586f606", "retrieved_at": "2026-10-09T08:58:28.868557+00:00", "evidence_level": "user_report_with_associated_photos_not_verified_diagnosis", "image_ownership_review": "pending_originality_check", "actual_work_order": false, "visual_review": "pending", "country": null, "license_url": "https://creativecommons.org/licenses/by-sa/4.0/", "assets": [{"id": "298906-0", "question_id": 298906, "category": "toilet_fault", "kind": "image", "url": "https://i.sstatic.net/4hpjs0gL.jpg", "alt": "enter image description here", "source_url": "https://diy.stackexchange.com/questions/298906/is-this-considered-a-running-toilet-recommend-fix", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 2048, "height": 1536, "final_url": "https://i.sstatic.net/4hpjs0gL.jpg", "local_path": "media/000/02.jpg", "sha256": "df9f62e943dd0c704eef2a2fd9d6580077ffdd60c5be33967afc22406dbbb35e", "retrieved_at": "2026-10-09T08:59:24.016269+00:00"}, {"id": "298906-1", "question_id": 298906, "category": "toilet_fault", "kind": "image", "url": "https://i.sstatic.net/rUNrGESk.jpg", "alt": "enter image description here", "source_url": "https://diy.stackexchange.com/questions/298906/is-this-considered-a-running-toilet-recommend-fix", "role": "reported_fault_context_candidate", "status": "success", "rights_status": "unknown", "width": 2048, "height": 1536, "final_url": "https://i.sstatic.net/rUNrGESk.jpg", "local_path": "media/000/03.jpg", "sha256": "95e8a89cceab23312a86018cb523b1281499fefcbc1cb1b326539f7ab1d48d34", "retrieved_at": "2026-10-09T08:59:25.886830+00:00"}]}, "image_count": 2}') ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, source_url=EXCLUDED.source_url, actual_work_order=EXCLUDED.actual_work_order, metadata=EXCLUDED.metadata;
