INSERT INTO collected_data.housing_records (id, dataset_type, name, city, region, address, source_url, metadata) VALUES ('general:home-docklands-1101787', 'general', 'East | 2 Bed | 2 Bath | C04', NULL, NULL, NULL, 'https://www.homeapartments.com.au/home-docklands/floorplans/east-%7C-2-bed-%7C-2-bath-%7C-c04', '{"id": "home-docklands-1101787", "name": "East | 2 Bed | 2 Bath | C04", "record_type": "source_record", "city": null, "region": null, "address": null, "property_id": "home-docklands", "category": null, "source_url": "https://www.homeapartments.com.au/home-docklands/floorplans/east-%7C-2-bed-%7C-2-bath-%7C-c04", "unit_number": null, "floor": null, "bedrooms": 2, "bathrooms": 2, "area_sqm": null, "price_raw": null, "author": null, "license": null, "license_url": null, "notes": null, "source_batch": "home-20260928T102421Z", "source_metadata": "home-20260928T102421Z\\assets.json", "image_ids": ["d423eed0d2f009781af581949fbd7b70d5d6480903e855ff0232cb9cd57a5184", "815d42b5b783dae72a995eea5d111a913e3098f1e15dbc36e4c1acfd5bfe16a0", "65451a95e4d674014aa75b15644fab330196ed51cdfc5d7b029b2066dc67b7bd", "f0b5908d82476af8e74a3a81e49fcb8c4296c46d654ca7676593ee1a2eae0a48", "a6ec218d0086d5fa55459ff75f391b30fd5a4c1f6a07cb12b3257549b8be9e91", "2881d1ccf8fca2f2cb6b89f597bcf61ee2c1b1502b4fd58e98938513b601eff6", "6619299d0e54901e2848390cf402a6d17322fd6358d1370c61ab1f010d7e96bf", "e67fe3b79bf22fbc5a652e1bcbb16b4f82862266fb1261f93fa45a3bf9398427", "cc07427dc5b3d977d168706885c45cdeb2a18818332edcbc7c0d228e8a5b84a1", "ef25718dd0e41dbe94911451cf69eb4d131cbccf43b62328dd5937ee5f4efbb5", "7efb2ec6db31ee57a2920a1efaf9c6f513c52018e383a5f64b9c2aec82161b78", "2c2ba3364197c8b1cd9abb276e033d9522e17d83ff93bc6f312a0dbbcadf461d", "34db55901ef1fcc8059ad9808f1b5c17400bc86ce3d336b1efda14251731cc1d"], "original_record": {"id": "home-docklands-1101787", "name": "East | 2 Bed | 2 Bath | C04", "source_company": "HOME", "relationship": "listed_on_brand_website", "legal_owner": null, "source_url": "https://www.homeapartments.com.au/home-docklands/floorplans/east-%7C-2-bed-%7C-2-bath-%7C-c04", "property_id": "home-docklands", "bedrooms": 2, "bathrooms": 2, "description": "Book your tour: https://www.homeapartments.com.au/book-a-tour/ \r\n\r\nPositioned in the heart of the Docklands and located just next door to the Marvel Stadium entertainment precinct -\r\n\r\n Home Docklands has been designed just for renters. This as new 2 bedroom, 2 bathroom apartment offer large kitchen with Island Bench, spacious living area, bedrooms, modern luxury and a high level of comfort. \r\n\r\nKey features include: \r\n- Practical and elegant bedrooms \r\n- Built-in robes - Ensuite bathroom to master \r\n- Sophisticated functional kitchen \r\n- Fisher & Paykel appliances\r\n -Integrated dishwasher \r\n- Spacious island bench with breakfast bar \r\n- Floor-to-ceiling windows \r\n- Large Private Balcony \r\n- All-year comfort with LG ducted air conditioning -\r\n Secure intercom system Enjoy the benefits and security of a long-term lease, 60-month lease terms are available.\r\n\r\n Please speak to our team for more information. We have an embedded electricity and Internet network, ensuring same-day connections and competitive pricing. You will also enjoy access to hotel style services and resident amenities including a co-working hub, pool, state-of-the-art gym, infrared sauna, podcast studio, private dining spaces, beats lounge and much more. *Images of display apartment. Outlook may vary from images used. \r\n\r\n*Parking options available", "retrieved_at": "2026-09-28T10:24:26.511855+00:00"}, "image_count": 13}') ON CONFLICT (id) DO UPDATE SET dataset_type=EXCLUDED.dataset_type, name=EXCLUDED.name, city=EXCLUDED.city, region=EXCLUDED.region, address=EXCLUDED.address, source_url=EXCLUDED.source_url, metadata=EXCLUDED.metadata;
