INSERT INTO collected_data.housing_records (id, dataset_type, name, city, region, address, source_url, metadata) VALUES ('general:ann', 'general', 'Level 13/446 Ann Street, Brisbane City QLD 4000', 'Brisbane', NULL, '"Level 13/446 Ann Street, Brisbane City QLD 4000"', 'https://www.homely.com.au/homes/level-13-446-ann-street-brisbane-city-qld-400/13467125', '{"id": "ann", "name": "Level 13/446 Ann Street, Brisbane City QLD 4000", "record_type": "source_record", "city": "Brisbane", "region": null, "address": "Level 13/446 Ann Street, Brisbane City QLD 4000", "property_id": null, "category": "Apartment", "source_url": "https://www.homely.com.au/homes/level-13-446-ann-street-brisbane-city-qld-400/13467125", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": {"@type": "Offer", "priceCurrency": "AUD", "price": "Fullly Furnished - $895 p/w", "url": "https://www.homely.com.au/homes/level-13-446-ann-street-brisbane-city-qld-400/13467125"}, "author": null, "license": "unknown", "license_url": null, "notes": ["historical_leased_not_current_offer"], "source_batch": "general-batch03-light-20261001", "source_metadata": "general-batch03-light-20261001\\media\\000\\outcomes.json", "image_ids": ["9eb0338cbbd08a35e628e277104482a600f20da3158b5b988accb5287a9b2a7b", "3dc60db6a0fca666d022f4184139916ced7cad0ae09af5583b629f10ba9d53be", "e98e8b7d59d5b1faccc99d5bf4396ad5a092d3fabe0a94191d726a6276f10cd9"], "original_record": {"id": "ann", "city": "Brisbane", "kind": "html", "url": "https://www.homely.com.au/homes/level-13-446-ann-street-brisbane-city-qld-400/13467125", "discovery": "public_search_result", "visual_status": "pending", "status": "success", "rights_status": "unknown", "final_url": "https://www.homely.com.au/homes/level-13-446-ann-street-brisbane-city-qld-400/13467125", "local_path": "00.html", "sha256": "3812ebf20102518583f9642117ff60d5b89308312e64e0b73249ad76b651b074", "retrieved_at": "2026-10-01T14:17:14.958962+00:00", "quality_accepted": false, "release_approved": false, "address": "Level 13/446 Ann Street, Brisbane City QLD 4000", "property_type": "Apartment", "description": "If you''re looking for an easy, comfortable move into the heart of Brisbane City, this spacious two-bedroom, two-bathroom apartment in Metropolis could be exactly what you''ve been waiting for. Offered fully furnished and exceptionally well equipped, there''s very little you''ll need to bring with you beyond your linen, towels, clothes and personal belongings. From the furniture and appliances to the outdoor setting, television, washer, dryer and even the microwave, everything has been thoughtfully set up for easy city living. Beautiful hybrid timber flooring flows throughout the apartment, creating a warm contemporary feel while also being practical and easy to maintain. Both bedrooms are generously proportioned and offer excellent built-in storage. The second bedroom includes a ceiling fan with integrated light, shelving, mirrored built-in wardrobe and quality bed and mattress. The main bedroom provides even more storage, with a three-door built-in wardrobe and a clever timber-framed gas-lift storage bed providing plenty of additional space beneath the mattress. A split-system air conditioner adds year-round comfort, while the adjoining ensuite includes a shower, vanity and toilet. The main bathroom is equally well presented, with a large mirror, vanity storage, shelving, shower and a double linen cupboard nearby. Directly opposite is the separate internal laundry, which comes fully equipped with a washing machine and dryer, large laundry tub, additional storage, ironing board and cleaning equipment. At the heart of the apartment is a spacious open-plan kitchen, living and dining area filled with natural light from the large glass sliding doors. The kitchen offers generous granite benchtops, timber cabinetry, double sink, pantry and plenty of storage, together with a quality fridge, Bosch dishwasher, electric oven, gas cooktop and microwave. The adjoining living and dining space comes complete with a large sofa, six-seater glass dining table, buffet, television and split-system air conditioning, making this a genuinely move-in-ready home rather than simply an apartment with a few pieces of furniture. Step outside and the lifestyle continues. The generous wraparound balcony includes outdoor lounge furniture and a high-bar setting, with an elevated outlook across Spring Hill towards Victoria Park and Fortitude Valley. It''s a fantastic additional living space whether you''re enjoying a morning coffee, an evening drink or simply taking in the city surrounds. And when convenience matters, you''re exceptionally well positioned, with Woolworths close by and Brisbane City, shopping, transport and surrounding inner-city precincts all within easy reach. Property features include: -\tFully furnished 2 bedroom, 2 bathroom apartment -\tSecure basement carpark -\tSpacious open-plan living and dining area -\tLarge wraparound balcony with outdoor furniture -\tElevated views towards Spring Hill, Victoria Park and Fortitude Valley -\tHybrid timber flooring throughout -\tSplit-system air conditioning to the living area and main bedroom -\tWell-equipped kitchen with granite benchtops and excellent storage -\tGas cooktop and electric oven -\tBosch dishwasher -\tFridge and microwave included -\tSix-seater dining setting -\tSofa, television and additional living room furniture included -\tMain bedroom with ensuite and three-door built-in wardrobe -\tGas-lift storage bed to the main bedroom -\tSecond bedroom with mirrored built-in wardrobe and ceiling fan -\tSeparate fully equipped laundry with washer and dryer -\tExcellent additional linen and household storage -\tConvenient Brisbane City location INSERT INTO collected_data.housing_media (housing_id, media_id, role) VALUES ('general:ann', '9eb0338cbbd08a35e628e277104482a600f20da3158b5b988accb5287a9b2a7b', 'layout_candidate') ON CONFLICT (housing_id, media_id) DO UPDATE SET role=EXCLUDED.role;
