INSERT INTO collected_data.housing_records (id, dataset_type, name, city, region, address, source_url, metadata) VALUES ('general:abeckett', 'general', '4805/135 A''Beckett Street, Melbourne VIC 3000', 'Melbourne', NULL, '"4805/135 A''Beckett Street, Melbourne VIC 3000"', 'https://www.homely.com.au/homes/4805-135-abeckett-street-melbourne-vic-3000/13548959', '{"id": "abeckett", "name": "4805/135 A''Beckett Street, Melbourne VIC 3000", "record_type": "source_record", "city": "Melbourne", "region": null, "address": "4805/135 A''Beckett Street, Melbourne VIC 3000", "property_id": null, "category": "Apartment", "source_url": "https://www.homely.com.au/homes/4805-135-abeckett-street-melbourne-vic-3000/13548959", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": {"@type": "Offer", "priceCurrency": "AUD", "price": "$750  per week", "url": "https://www.homely.com.au/homes/4805-135-abeckett-street-melbourne-vic-3000/13548959", "availability": "https://schema.org/InStock"}, "author": null, "license": "unknown", "license_url": null, "notes": null, "source_batch": "general-batch03-light-20261001", "source_metadata": "general-batch03-light-20261001\\media\\000\\outcomes.json", "image_ids": ["b771d0d3db0ee51d38c1b4a08e190c79b9d1db33614b9d17ad8a5758e5eaaacb", "a686e6aea2ed95951f9dad671fdd2809b12472c35fe661cad9dc7603f0dbb81b", "1478d478af42eca2031050bb3905ef181bb993bbb06dc2f4675f193b0d272bbe"], "original_record": {"id": "abeckett", "city": "Melbourne", "kind": "html", "url": "https://www.homely.com.au/homes/4805-135-abeckett-street-melbourne-vic-3000/13548959", "discovery": "public_search_result", "visual_status": "pending", "status": "success", "rights_status": "unknown", "final_url": "https://www.homely.com.au/homes/4805-135-abeckett-street-melbourne-vic-3000/13548959", "local_path": "01.html", "sha256": "e103d706a2685358522440bf5256071c3d1f38f0846d4186ab55714bf1260fcb", "retrieved_at": "2026-10-01T14:17:16.878035+00:00", "qua