INSERT INTO collected_data.housing_records (id, dataset_type, name, city, region, address, source_url, metadata) VALUES ('general:toorak', 'general', '7/717 Toorak Road, Kooyong VIC 3144', 'Melbourne', NULL, '"7/717 Toorak Road, Kooyong VIC 3144"', 'https://www.homely.com.au/homes/7-717-toorak-road-kooyong-vic-3144/13427026', '{"id": "toorak", "name": "7/717 Toorak Road, Kooyong VIC 3144", "record_type": "source_record", "city": "Melbourne", "region": null, "address": "7/717 Toorak Road, Kooyong VIC 3144", "property_id": null, "category": "Apartment", "source_url": "https://www.homely.com.au/homes/7-717-toorak-road-kooyong-vic-3144/13427026", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": {"@type": "Offer", "priceCurrency": "AUD", "price": "$1300pw", "url": "https://www.homely.com.au/homes/7-717-toorak-road-kooyong-vic-3144/13427026", "availability": "https://schema.org/InStock"}, "author": null, "license": "unknown", "license_url": null, "notes": null, "source_batch": "general-batch03-light-20261001", "source_metadata": "general-batch03-light-20261001\\media\\040\\outcomes.json", "image_ids": ["e17c7332859e5f7569b7fcc35ff84950671cdae67547826e8d465947db0c02c3", "3845221c554f86d55b11dd07c4fa67c831dd6ce8367dd1725107cb6ab6b5715c", "c88954ff6d95bb4660f698bb5e797b1d281d708ffb86798448f8769ee5cb7aec"], "original_record": {"id": "toorak", "city": "Melbourne", "kind": "html", "url": "https://www.homely.com.au/homes/7-717-toorak-road-kooyong-vic-3144/13427026", "discovery": "public_search_result", "visual_status": "pending", "status": "success", "rights_status": "unknown", "final_url": "https://www.homely.com.au/homes/7-717-toorak-road-kooyong-vic-3144/13427026", "local_path": "13.html", "sha256": "ea028e348fa76f41b922e8db883f33b5ba26a6c004bfe7f5c9866d61d13fc9bb", "retrieved_at": "2026-10-01T14:17:41.007246+00:00", "quality_accepted": false, "release_approved": false, "address": "7/717 Toorak Road, Kooyong VIC 3144", "property_type": "Apartment", "description": "***Available from now until 31st of March 2027*** Privately positioned at the rear of an exclusive boutique development of just eight residences, this exceptional three-bedroom apartment delivers a rare standard of space, privacy and sophistication in one of Melbourne''s most prestigious residential pockets. With approximately 136sqm of beautifully appointed internal living and an extraordinary 30sqm covered north-facing terrace, the residence offers proportions more reminiscent of a home than an apartment. Elevated above its leafy surrounds and enjoying treetop views across Kooyong towards Hawthorn and Camberwell, the home is wonderfully secluded and filled with natural northern light. Expansive living and dining areas connect seamlessly with the terrace, creating an impressive indoor-outdoor environment for both everyday living and entertaining. The magnificent 15-metre-long terrace is undoubtedly a highlight. Accessible from both the living areas and main bedroom, and framed by established landscaped planter gardens, it provides a private outdoor sanctuary with a beautiful leafy outlook and ample space for alfresco dining, entertaining and relaxing throughout the year. The quality continues throughout the interiors, with rich hardwood parquetry flooring, marble finishes and a superbly appointed kitchen featuring premium Miele appliances and Qasair rangehood. Accommodation is equally impressive, comprising three generously proportioned bedrooms with extensive custom-built storage, including approximately three metres of built-in robes to each bedroom. The main suite enjoys direct access to the terrace together with a luxurious marble-appointed ensuite. **PROPERTY FEATURES:** * Approximately 136sqm of internal living * Expansive 30sqm covered north-facing terrace * Exceptional 15-metre terrace with landscaped planter gardens * Three generous bedrooms with extensive custom-built robes * Main bedroom with terrace access and marble-appointed ensuite * Second luxurious marble bathroom * Generous open-plan living and dining with direct terrace access * Elevated treetop views across Kooyong towards Hawthorn and Camberwell * Exceptional privacy and natural northern light * Beautiful hardwood parquetry flooring * Premium marble finishes * Gourmet kitchen with Miele appliances and Qasair rangehood * Separate full-size laundry with excellent storage * Zoned central heating and cooling * Secure intercom entry * Two side-by-side basement car spaces, ideally positioned closest to the lift * Secure storage cage **AN EXCEPTIONAL KOOYONG LIFESTYLE** Opposite Sir Robert Menzies Reserve and surrounded by some of Melbourne''s finest homes, the location places an outstanding selection of amenities within easy reach. Stroll to Kooyong Village and Kooyong Station, with Toorak Road and Glenferrie Road trams, Hawthorn shopping and dining, Gardiners Creek parklands and the KooyongKoot walking and cycling trails all nearby. The property is also superbly positioned for access to many of Melbourne''s leading private schools, while convenient freeway connections provide easy access to the CBD, Melbourne Airport and the Mornington Peninsula. Offering remarkable space, an exceptional outdoor environment and a level of privacy rarely associated with apartment living, this is a distinctive opportunity to enjoy refined, low-maintenance living in tightly held Kooyong. Please click this link for a video tour of the property: https://virtual-tour.ipropertyexpress.com/vt/tour/9fbbdf4c-3dcb-41c8-9bce-3a1d7c4bbf3d ***Please note owners corporation rules apply to this property - move in move out policy also applies***", "offer": {"@type": "Offer", "priceCurrency": "AUD", "price": "$1300pw", "url": "https://www.homely.com.au/homes/7-717-toorak-road-kooyong-vic-3144/13427026", "availability": "https://schema.org/InStock"}, "page_title": "7/717 Toorak Road, Kooyong VIC 3144 - Apartment For Rent", "source_modified_at": "2026-10-01T00:31:38.436Z", "flags": [], "linked_media_count": 9, "selected_media_count": 3, "selection_policy": "all_linked_plans_and_first_gallery_candidates", "gallery_limit": 2, "linked_layout_count": 1}, "image_count": 3}') ON CONFLICT (id) DO UPDATE SET dataset_type=EXCLUDED.dataset_type, name=EXCLUDED.name, city=EXCLUDED.city, region=EXCLUDED.region, address=EXCLUDED.address, source_url=EXCLUDED.source_url, metadata=EXCLUDED.metadata;
