INSERT INTO collected_data.housing_records (id, dataset_type, name, city, region, address, source_url, metadata) VALUES ('general:bank', 'general', '1111/38 Bank Street, South Melbourne VIC 3205', 'Melbourne', NULL, '"1111/38 Bank Street, South Melbourne VIC 3205"', 'https://www.homely.com.au/homes/1111-38-bank-street-south-melbourne-vic-3205/13531308', '{"id": "bank", "name": "1111/38 Bank Street, South Melbourne VIC 3205", "record_type": "source_record", "city": "Melbourne", "region": null, "address": "1111/38 Bank Street, South Melbourne VIC 3205", "property_id": null, "category": "Apartment", "source_url": "https://www.homely.com.au/homes/1111-38-bank-street-south-melbourne-vic-3205/13531308", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": {"@type": "Offer", "priceCurrency": "AUD", "price": "$1,000 per week", "url": "https://www.homely.com.au/homes/1111-38-bank-street-south-melbourne-vic-3205/13531308", "availability": "https://schema.org/InStock"}, "author": null, "license": "unknown", "license_url": null, "notes": ["illustrative_media_disclaimer_review_required"], "source_batch": "general-batch03-light-20261001", "source_metadata": "general-batch03-light-20261001\\media\\040\\outcomes.json", "image_ids": ["d7b970a9015ff154e8347ebe2499a57dcde4f532ce315e6ac6611807b0a3bdb5", "3aadd05a5df2eabcc59406d697fe953a8dcea7116bddd004885826996684e8b9", "1abcd3e2234dc0fdefc571810304797ded95829c7b8beedb827cdaf9b006f258"], "original_record": {"id": "bank", "city": "Melbourne", "kind": "html", "url": "https://www.homely.com.au/homes/1111-38-bank-street-south-melbourne-vic-3205/13531308", "discovery": "public_search_result", "visual_status": "pending", "status": "success", "rights_status": "unknown", "final_url": "https://www.homely.com.au/homes/1111-38-bank-street-south-melbourne-vic-3205/13531308", "local_path": "16.html", "sha256": "8ac5b9d21360e81372e228691bc581aaf01a9b7f8865bd9cbc851f8bf86374ab", "retrieved_at": "2026