INSERT INTO collected_data.housing_records (id, dataset_type, name, city, region, address, source_url, metadata) VALUES ('general:pirie312', 'general', '312/297 Pirie Street, Adelaide SA 5000', 'Adelaide', NULL, '"312/297 Pirie Street, Adelaide SA 5000"', 'https://www.homely.com.au/homes/312-297-pirie-street-adelaide-sa-5000/12620730', '{"id": "pirie312", "name": "312/297 Pirie Street, Adelaide SA 5000", "record_type": "source_record", "city": "Adelaide", "region": null, "address": "312/297 Pirie Street, Adelaide SA 5000", "property_id": null, "category": "Apartment", "source_url": "https://www.homely.com.au/homes/312-297-pirie-street-adelaide-sa-5000/12620730", "unit_number": null, "floor": null, "bedrooms": null, "bathrooms": null, "area_sqm": null, "price_raw": {"@type": "Offer", "priceCurrency": "AUD", "price": "Price Undisclosed", "url": "https://www.homely.com.au/homes/312-297-pirie-street-adelaide-sa-5000/12620730"}, "author": null, "license": "unknown", "license_url": null, "notes": ["historical_leased_not_current_offer"], "source_batch": "general-batch03-light-20261001", "source_metadata": "general-batch03-light-20261001\\media\\040\\outcomes.json", "image_ids": ["f05e1bd4097502ab752f6c8125e61cd286e39f82c08f38ada659979644812671", "62375cf61ca7f18f6107a31cb1978fd929322a50445496c7ce6c92526a872b26", "09386cb9103482bd183d7dd9ba09a4e83f98e2bb639a02ccf32e331f417e3c9e"], "original_record": {"id": "pirie312", "city": "Adelaide", "kind": "html", "url": "https://www.homely.com.au/homes/312-297-pirie-street-adelaide-sa-5000/12620730", "discovery": "public_search_result", "visual_status": "pending", "status": "success", "rights_status": "unknown", "final_url": "https://www.homely.com.au/homes/312-297-pirie-street-adelaide-sa-5000/12620730", "local_path": "19.html", "sha256": "958a45a811f9a18bb7441e1fcdd16bf673ec4db0b639ff8a038a5ad97d1d7285", "retrieved_at": "2026-10-01T14:17:52.827666+00:00", "quality_accepted": false, "release_approved": false, "address": "312/297 Pirie Street, Adelaide SA 5000", "property_type": "Apartment", "description": "TENANCY INFORMATION Furnished: Fully furnished Pets: Negotiable Smoke: Not permitted sorry Bond: 4 weeks bond Lease term: 12 months ----------------------------- Modern architectural apartments situated at the heart of the east end of Adelaide City will bring your busy city life full of comfort and ease of mind. This apartment provides a 360-degree panoramic view of Adelaide city with the floor of the feature ceiling window and glass-embraced balcony. Furthermore, high-end timber has been used for the flooring to create a naturally comfortable environment for your house to call home. For your weekend activities or daily exercise, this apartment has surrounded by parklands parks, botanica gardens, and all the famous restaurants located nearby. For educational wise, Adelaide botanic high school and the University of Adelaide just a minute from your door. What we love about this apartment: * Open plan kitchen and living area with split system heating and cooling. * A spacious balcony is accessed from the living room and also enjoys the view. * The kitchen includes a dishwasher and electric cooktop. * European laundry. * Main bedroom has a large built-in wardrobe, Ensuite. * Second bedroom with ceiling fan and built-in robe and floor to ceiling window. * Sparkling bathroom with floor to ceiling tiles, storage to the vanity, and large shower alcove. * Natural light to all bedrooms and living areas. Other features: • 15 Storeys • 140 Apartments • Double Glazed Windows • Timber Floors in the living area • Carpets in the bedrooms • Porcelain tiles in bathroom • Spacious balconies • Stone benchtop • 60m to Hutt Street • 350m to Rundle Street • Within 200m of Major Transport (O-Bahn) • 500m to the Tram (Botanic station) 𝑫𝑰𝑺𝑪𝑳𝑨𝑰𝑴𝑬𝑹 Online applications are available by the APPLY button via this listing or please feel free to contact Stephy 0452 066 853 or Calvin 0433 998 723 RLA: 272 867 *Please note that all the information that has been provided for this property has been obtained from sources we believe to be accurate. We cannot guarantee the information is accurate however and we accept no liability for any errors or omissions – including, but not limited to the property''s land size, floor plans & dimensions, build size, building age, condition, or any other particulars. Interested parties should always make their own inquiries and obtain their own legal advice.", "offer": {"@type": "Offer", "priceCurrency": "AUD", "price": "Price Undisclosed", "url": "https://www.homely.com.au/homes/312-297-pirie-street-adelaide-sa-5000/12620730"}, "page_title": "Leased Apartment 312/297 Pirie Street, Adelaide SA 5000 - Dec 15, 2025", "source_modified_at": "2025-12-15T05:33:03.876Z", "flags": ["historical_leased_not_current_offer"], "linked_media_count": 11, "selected_media_count": 3, "selection_policy": "all_linked_plans_and_first_gallery_candidates", "gallery_limit": 2, "linked_layout_count": 1}, "image_count": 3}') ON CONFLICT (id) DO UPDATE SET dataset_type=EXCLUDED.dataset_type, name=EXCLUDED.name, city=EXCLUDED.city, region=EXCLUDED.region, address=EXCLUDED.address, source_url=EXCLUDED.source_url, metadata=EXCLUDED.metadata;
